import numpy as np
import librosa


def _extract_single_feature(audio_path: str) -> np.ndarray:
    default_feature = np.zeros(40, dtype=np.float64)

    try:
        y, sr = librosa.load(audio_path, sr=None, mono=True)
    except Exception:
        return default_feature

    if y is None or sr is None or sr <= 0:
        return default_feature

    y = np.asarray(y, dtype=np.float32)
    if y.size == 0:
        return default_feature

    win_length = max(1, int(round(0.025 * sr)))
    hop_length = max(1, int(round(0.010 * sr)))
    n_fft = win_length

    try:
        mfcc = librosa.feature.mfcc(
            y=y,
            sr=sr,
            n_mfcc=20,
            n_fft=n_fft,
            hop_length=hop_length,
            win_length=win_length,
        )
    except Exception:
        return default_feature

    if mfcc.ndim != 2 or mfcc.shape[0] != 20 or mfcc.shape[1] == 0:
        return default_feature

    mean = np.mean(mfcc, axis=1)
    std = np.std(mfcc, axis=1)
    feat = np.concatenate([mean, std]).astype(np.float64, copy=False)
    feat = np.nan_to_num(feat, nan=0.0, posinf=0.0, neginf=0.0)

    if feat.shape != (40,):
        return default_feature

    return feat


def feature_fn(data_subset):
    features = [_extract_single_feature(audio_path) for audio_path in data_subset]
    if len(features) == 0:
        return np.empty((0, 40), dtype=np.float64)

    X_subset = np.vstack(features).astype(np.float64, copy=False)
    X_subset = np.nan_to_num(X_subset, nan=0.0, posinf=0.0, neginf=0.0)
    return X_subset

import numpy as np
import librosa


def _safe_delta(feat):
    n_frames = feat.shape[1]
    if n_frames < 3:
        return np.zeros_like(feat, dtype=np.float64)
    width = min(9, n_frames if n_frames % 2 == 1 else n_frames - 1)
    if width < 3:
        return np.zeros_like(feat, dtype=np.float64)
    return librosa.feature.delta(feat, width=width, order=1, mode="nearest")


def _extract_one(path):
    try:
        y, sr = librosa.load(path, sr=None, mono=True)
        y = np.asarray(y, dtype=np.float64)
        if y.size == 0 or sr is None or sr <= 0:
            return np.zeros(120, dtype=np.float64)

        frame_length = max(1, int(round(0.025 * sr)))
        hop_length = max(1, int(round(0.010 * sr)))
        n_fft = max(2, frame_length)

        mfcc = librosa.feature.mfcc(
            y=y,
            sr=sr,
            n_mfcc=20,
            n_fft=n_fft,
            hop_length=hop_length,
            win_length=frame_length,
            center=False,
        )
        mfcc = np.asarray(mfcc, dtype=np.float64)

        if mfcc.ndim != 2 or mfcc.shape[0] != 20:
            return np.zeros(120, dtype=np.float64)

        delta = _safe_delta(mfcc)
        delta2 = _safe_delta(delta)
        stacked = np.vstack([mfcc, delta, delta2])

        means = np.mean(stacked, axis=1)
        stds = np.std(stacked, axis=1)
        features = np.concatenate([means, stds], axis=0).astype(np.float64, copy=False)

        if features.shape != (120,):
            return np.zeros(120, dtype=np.float64)

        features = np.nan_to_num(features, nan=0.0, posinf=0.0, neginf=0.0)
        return features
    except Exception:
        return np.zeros(120, dtype=np.float64)


def feature_fn(data_subset):
    features = [_extract_one(path) for path in data_subset]
    if len(features) == 0:
        return np.zeros((0, 120), dtype=np.float64)
    X_subset = np.vstack(features).astype(np.float64, copy=False)
    X_subset = np.nan_to_num(X_subset, nan=0.0, posinf=0.0, neginf=0.0)
    return X_subset

import numpy as np
from scipy.io import wavfile


def _load_audio_mono(path):
    sr, audio = wavfile.read(path)
    audio = np.asarray(audio)

    if audio.ndim > 1:
        audio = audio.mean(axis=1)

    if np.issubdtype(audio.dtype, np.integer):
        max_abs = max(abs(np.iinfo(audio.dtype).min), abs(np.iinfo(audio.dtype).max))
        audio = audio.astype(np.float64) / float(max_abs if max_abs > 0 else 1.0)
    else:
        audio = audio.astype(np.float64, copy=False)

    return sr, audio


def _frame_rms(audio, frame_length, hop_length):
    if audio.size == 0:
        return np.zeros(1, dtype=np.float64)

    if audio.size < frame_length:
        pad_width = frame_length - audio.size
        audio = np.pad(audio, (0, pad_width), mode="constant")

    n_frames = 1 + (audio.size - frame_length) // hop_length
    starts = np.arange(n_frames, dtype=np.int64) * hop_length
    frames = np.stack([audio[start:start + frame_length] for start in starts], axis=0)
    rms = np.sqrt(np.mean(frames * frames, axis=1))
    return rms.astype(np.float64, copy=False)


def _summarize_rms(rms):
    rms = np.asarray(rms, dtype=np.float64)
    if rms.size == 0:
        return np.zeros(8, dtype=np.float64)

    mean_val = float(np.mean(rms))
    std_val = float(np.std(rms))
    min_val = float(np.min(rms))
    max_val = float(np.max(rms))
    range_val = max_val - min_val

    if std_val > 1e-12:
        centered = rms - mean_val
        m3 = float(np.mean(centered ** 3))
        m4 = float(np.mean(centered ** 4))
        skew_val = m3 / (std_val ** 3)
        kurt_val = (m4 / (std_val ** 4)) - 3.0
    else:
        skew_val = 0.0
        kurt_val = 0.0

    ratio_val = max_val / mean_val if mean_val > 1e-12 else 0.0

    feats = np.array(
        [mean_val, std_val, min_val, max_val, range_val, skew_val, kurt_val, ratio_val],
        dtype=np.float64,
    )
    return np.nan_to_num(feats, nan=0.0, posinf=0.0, neginf=0.0)


def feature_fn(data_subset):
    features = []

    for path in data_subset:
        try:
            sr, audio = _load_audio_mono(path)
            frame_length = max(1, int(round(0.025 * sr)))
            hop_length = max(1, int(round(0.010 * sr)))
            rms = _frame_rms(audio, frame_length=frame_length, hop_length=hop_length)
            feats = _summarize_rms(rms)
        except Exception:
            feats = np.zeros(8, dtype=np.float64)

        features.append(feats)

    if not features:
        return np.zeros((0, 8), dtype=np.float64)

    X_subset = np.vstack(features).astype(np.float64, copy=False)
    X_subset = np.nan_to_num(X_subset, nan=0.0, posinf=0.0, neginf=0.0)
    return X_subset

import numpy as np
import librosa


def _extract_spectral_contrast_features(audio_path):
    feature_dim = 14
    try:
        y, sr = librosa.load(audio_path, sr=None, mono=True)
        if y.size == 0 or sr is None or sr <= 0:
            return np.zeros(feature_dim, dtype=np.float64)

        n_fft = max(32, int(round(0.025 * sr)))
        hop_length = max(1, int(round(0.010 * sr)))

        if y.size < n_fft:
            y = np.pad(y, (0, n_fft - y.size), mode="constant")

        contrast = librosa.feature.spectral_contrast(
            y=y,
            sr=sr,
            n_fft=n_fft,
            hop_length=hop_length
        )

        if contrast.ndim != 2 or contrast.shape[0] != 7:
            return np.zeros(feature_dim, dtype=np.float64)

        mean_feat = np.mean(contrast, axis=1)
        std_feat = np.std(contrast, axis=1)
        feats = np.concatenate([mean_feat, std_feat]).astype(np.float64, copy=False)

        if feats.shape[0] != feature_dim:
            return np.zeros(feature_dim, dtype=np.float64)

        feats = np.nan_to_num(feats, nan=0.0, posinf=0.0, neginf=0.0)
        return feats
    except Exception:
        return np.zeros(feature_dim, dtype=np.float64)


def feature_fn(data_subset):
    features = [_extract_spectral_contrast_features(audio_path) for audio_path in data_subset]
    if len(features) == 0:
        return np.zeros((0, 14), dtype=np.float64)
    X_subset = np.vstack(features).astype(np.float64, copy=False)
    X_subset = np.nan_to_num(X_subset, nan=0.0, posinf=0.0, neginf=0.0)
    return X_subset

