import numpy as np
import librosa
from scipy.stats import skew, kurtosis


N_MFCC = 20
STATIC_STATS_PER_COEFF = 7
DELTA_STATS_PER_COEFF = 2
OUTPUT_DIM = N_MFCC * (STATIC_STATS_PER_COEFF + DELTA_STATS_PER_COEFF)


def _safe_stats(matrix):
    mean = np.mean(matrix, axis=1)
    std = np.std(matrix, axis=1)
    min_ = np.min(matrix, axis=1)
    max_ = np.max(matrix, axis=1)
    median = np.median(matrix, axis=1)
    skewness = skew(matrix, axis=1, bias=False, nan_policy="omit")
    kurt = kurtosis(matrix, axis=1, fisher=True, bias=False, nan_policy="omit")
    features = np.concatenate([mean, std, min_, max_, median, skewness, kurt]).astype(np.float64, copy=False)
    return np.nan_to_num(features, nan=0.0, posinf=0.0, neginf=0.0)


def _delta_stats(matrix):
    mean = np.mean(matrix, axis=1)
    std = np.std(matrix, axis=1)
    features = np.concatenate([mean, std]).astype(np.float64, copy=False)
    return np.nan_to_num(features, nan=0.0, posinf=0.0, neginf=0.0)


def _compute_delta(mfcc):
    n_frames = mfcc.shape[1]
    if n_frames < 3:
        return np.zeros_like(mfcc, dtype=np.float64)
    width = min(9, n_frames)
    if width % 2 == 0:
        width -= 1
    if width < 3:
        return np.zeros_like(mfcc, dtype=np.float64)
    delta = librosa.feature.delta(mfcc, width=width, order=1, axis=-1)
    return np.asarray(delta, dtype=np.float64)


def _extract_one(audio_path):
    try:
        y, sr = librosa.load(audio_path, sr=None, mono=True)
        y = np.asarray(y, dtype=np.float64)
        if y.size == 0:
            return np.zeros(OUTPUT_DIM, dtype=np.float64)

        mfcc = librosa.feature.mfcc(y=y, sr=sr, n_mfcc=N_MFCC)
        mfcc = np.asarray(mfcc, dtype=np.float64)
        if mfcc.ndim != 2 or mfcc.shape[0] != N_MFCC or mfcc.shape[1] == 0:
            return np.zeros(OUTPUT_DIM, dtype=np.float64)

        delta = _compute_delta(mfcc)

        static_features = _safe_stats(mfcc)
        delta_features = _delta_stats(delta)
        features = np.concatenate([static_features, delta_features]).astype(np.float64, copy=False)

        if features.shape[0] != OUTPUT_DIM:
            fixed = np.zeros(OUTPUT_DIM, dtype=np.float64)
            fixed[: min(OUTPUT_DIM, features.shape[0])] = features[:OUTPUT_DIM]
            features = fixed

        return np.nan_to_num(features, nan=0.0, posinf=0.0, neginf=0.0)
    except Exception:
        return np.zeros(OUTPUT_DIM, dtype=np.float64)


def feature_fn(data_subset):
    features = [_extract_one(audio_path) for audio_path in data_subset]
    if len(features) == 0:
        return np.zeros((0, OUTPUT_DIM), dtype=np.float64)
    X_subset = np.vstack(features).astype(np.float64, copy=False)
    return np.nan_to_num(X_subset, nan=0.0, posinf=0.0, neginf=0.0)

import numpy as np
import librosa
from scipy.stats import skew, kurtosis


def _safe_stat_vector(values, stat_names):
    values = np.asarray(values, dtype=np.float64)
    if values.ndim != 1:
        values = values.reshape(-1)
    if values.size == 0:
        return np.zeros(len(stat_names), dtype=np.float64)

    out = []
    for name in stat_names:
        if name == "mean":
            val = np.mean(values)
        elif name == "std":
            val = np.std(values)
        elif name == "min":
            val = np.min(values)
        elif name == "max":
            val = np.max(values)
        elif name == "median":
            val = np.median(values)
        elif name == "range":
            val = np.max(values) - np.min(values)
        elif name == "skew":
            val = skew(values, bias=False)
        elif name == "kurtosis":
            val = kurtosis(values, fisher=True, bias=False)
        else:
            raise ValueError(f"Unsupported stat: {name}")

        if not np.isfinite(val):
            val = 0.0
        out.append(float(val))

    return np.asarray(out, dtype=np.float64)


def _aggregate_frame_matrix(frame_matrix, stat_names):
    frame_matrix = np.asarray(frame_matrix, dtype=np.float64)
    if frame_matrix.ndim != 2:
        raise ValueError("Expected a 2D frame matrix.")
    if frame_matrix.shape[1] == 0:
        return np.zeros(frame_matrix.shape[0] * len(stat_names), dtype=np.float64)

    features = []
    for row in frame_matrix:
        features.append(_safe_stat_vector(row, stat_names))
    return np.concatenate(features, axis=0).astype(np.float64, copy=False)


def _extract_one(path):
    mfcc_stats = ["mean", "std", "min", "max", "median", "skew", "kurtosis"]
    f0_stats = ["mean", "std", "range", "median", "skew", "kurtosis"]
    rms_stats = ["mean", "std", "min", "max", "skew", "kurtosis"]

    try:
        y, sr = librosa.load(path, sr=None, mono=True)
        y = np.asarray(y, dtype=np.float64)
    except Exception:
        return np.zeros(153, dtype=np.float64)

    if y.size == 0:
        return np.zeros(153, dtype=np.float64)

    try:
        mfcc = librosa.feature.mfcc(y=y, sr=sr, n_mfcc=20)
        mfcc_block = _aggregate_frame_matrix(mfcc, mfcc_stats)
    except Exception:
        mfcc_block = np.zeros(140, dtype=np.float64)

    try:
        f0, voiced_flag, _ = librosa.pyin(y, sr=sr)
        voiced_mask = np.isfinite(f0)
        voiced_fraction = float(np.mean(voiced_mask)) if f0 is not None and len(f0) > 0 else 0.0
        if np.any(voiced_mask):
            voiced_f0 = np.asarray(f0[voiced_mask], dtype=np.float64)
            f0_block = _safe_stat_vector(voiced_f0, f0_stats)
        else:
            f0_block = np.zeros(6, dtype=np.float64)
            voiced_fraction = 0.0
        f0_block = np.concatenate([f0_block, np.asarray([voiced_fraction], dtype=np.float64)], axis=0)
    except Exception:
        f0_block = np.zeros(7, dtype=np.float64)

    try:
        rms = librosa.feature.rms(y=y).reshape(-1)
        rms_block = _safe_stat_vector(rms, rms_stats)
    except Exception:
        rms_block = np.zeros(6, dtype=np.float64)

    feat = np.concatenate([mfcc_block, f0_block, rms_block], axis=0).astype(np.float64, copy=False)
    if feat.shape[0] != 153:
        fixed = np.zeros(153, dtype=np.float64)
        fixed[: min(153, feat.shape[0])] = feat[:153]
        feat = fixed
    feat[~np.isfinite(feat)] = 0.0
    return feat


def feature_fn(data_subset):
    features = [_extract_one(path) for path in data_subset]
    if len(features) == 0:
        return np.zeros((0, 153), dtype=np.float64)
    X_subset = np.vstack(features).astype(np.float64, copy=False)
    X_subset[~np.isfinite(X_subset)] = 0.0
    return X_subset

import numpy as np
import librosa


def _regression_features(mfcc_matrix: np.ndarray) -> np.ndarray:
    n_coeffs, n_frames = mfcc_matrix.shape
    means = mfcc_matrix.mean(axis=1)
    stds = mfcc_matrix.std(axis=1)

    slopes = np.zeros(n_coeffs, dtype=np.float64)
    curvatures = np.zeros(n_coeffs, dtype=np.float64)

    if n_frames >= 2:
        x = np.linspace(0.0, 1.0, n_frames, dtype=np.float64)
        for i in range(n_coeffs):
            y = mfcc_matrix[i].astype(np.float64, copy=False)
            slopes[i] = np.polyfit(x, y, deg=1)[0]
            if n_frames >= 3:
                curvatures[i] = np.polyfit(x, y, deg=2)[0]

    features = np.concatenate([means, stds, slopes, curvatures], axis=0)
    features = np.nan_to_num(features, nan=0.0, posinf=0.0, neginf=0.0)
    return features.astype(np.float64, copy=False)


def _extract_single(path: str) -> np.ndarray:
    try:
        y, sr = librosa.load(path, sr=None, mono=True)
        if y.size == 0:
            return np.zeros(80, dtype=np.float64)
        mfcc = librosa.feature.mfcc(y=y, sr=sr, n_mfcc=20)
        if mfcc.ndim != 2 or mfcc.shape[0] != 20 or mfcc.shape[1] == 0:
            return np.zeros(80, dtype=np.float64)
        return _regression_features(mfcc)
    except Exception:
        return np.zeros(80, dtype=np.float64)


def feature_fn(data_subset):
    features = [_extract_single(path) for path in data_subset]
    if not features:
        return np.zeros((0, 80), dtype=np.float64)
    X_subset = np.vstack(features).astype(np.float64, copy=False)
    X_subset = np.nan_to_num(X_subset, nan=0.0, posinf=0.0, neginf=0.0)
    return X_subset

