def _safe_stat_agg(frame_feature_matrix: np.ndarray) -> np.ndarray:
    if frame_feature_matrix.ndim != 2 or frame_feature_matrix.shape[1] == 0:
        return np.zeros(frame_feature_matrix.shape[0] * 7, dtype=np.float64)

