    max_ = np.max(frame_feature_matrix, axis=1)
    median = np.median(frame_feature_matrix, axis=1)
    sk = skew(frame_feature_matrix, axis=1, bias=False, nan_policy="omit")
    kt = kurtosis(frame_feature_matrix, axis=1, bias=False, nan_policy="omit")

    feats = np.concatenate([mean, std, min_, max_, median, sk, kt]).astype(np.float64, copy=False)
    return np.nan_to_num(feats, nan=0.0, posinf=0.0, neginf=0.0)


def _safe_mean_std_agg(frame_feature_matrix: np.ndarray) -> np.ndarray:
    if frame_feature_matrix.ndim != 2 or frame_feature_matrix.shape[1] == 0:
        return np.zeros(frame_feature_matrix.shape[0] * 2, dtype=np.float64)

