def _aggregate_framewise(feature_matrix, stats_to_use):
    feature_matrix = np.asarray(feature_matrix, dtype=np.float64)
    if feature_matrix.ndim != 2:
        feature_matrix = np.atleast_2d(feature_matrix)
    if feature_matrix.shape[1] == 0:
        feature_matrix = np.zeros((feature_matrix.shape[0], 1), dtype=np.float64)

    aggregated = []
    for stat_name in stats_to_use:
