        else:
            raise ValueError(f"Unsupported statistic: {stat_name}")
        aggregated.append(_safe_stat_array(stat_values))

    return np.concatenate(aggregated, axis=0)


def _extract_single(audio_path):
    if not isinstance(audio_path, str) or not os.path.exists(audio_path):
        return np.zeros(_FEATURE_DIM, dtype=np.float64)

    try:
        y, sr = librosa.load(audio_path, sr=_SR, mono=True)
        if y.size == 0:
            return np.zeros(_FEATURE_DIM, dtype=np.float64)

        mfcc = librosa.feature.mfcc(
            y=y,
            sr=sr,
            n_mfcc=_MFCC_DIM,
            n_fft=_N_FFT,
            hop_length=_HOP_LENGTH,
        )
        mfcc_features = _aggregate_framewise(mfcc, _MFCC_STATS)

        spectral_contrast = librosa.feature.spectral_contrast(
            y=y,
            sr=sr,
            n_fft=_N_FFT,
            hop_length=_HOP_LENGTH,
            n_bands=6,
        )
        contrast_features = _aggregate_framewise(spectral_contrast, _SC_STATS)

        features = np.concatenate([mfcc_features, contrast_features], axis=0)
        if features.shape[0] != _FEATURE_DIM:
            fixed = np.zeros(_FEATURE_DIM, dtype=np.float64)
            fixed[: min(_FEATURE_DIM, features.shape[0])] = features[:_FEATURE_DIM]
            features = fixed

        return _safe_stat_array(features)
    except Exception:
        return np.zeros(_FEATURE_DIM, dtype=np.float64)


def feature_fn(data_subset):
    features = [_extract_single(audio_path) for audio_path in data_subset]
    if len(features) == 0:
        return np.zeros((0, _FEATURE_DIM), dtype=np.float64)
    X_subset = np.vstack(features).astype(np.float64, copy=False)
    X_subset = np.nan_to_num(X_subset, nan=0.0, posinf=0.0, neginf=0.0)
    return X_subset

import numpy as np
import librosa
from scipy.stats import skew, kurtosis


_EXPECTED_DIM = 163


def _nan_to_num_array(x):
    x = np.asarray(x, dtype=np.float64)
    return np.nan_to_num(x, nan=0.0, posinf=0.0, neginf=0.0)


def _safe_skew(row):
    try:
        value = skew(row, bias=False, nan_policy="omit")
    except Exception:
        value = 0.0
    value = np.asarray(value, dtype=np.float64)
    return float(np.nan_to_num(value, nan=0.0, posinf=0.0, neginf=0.0))


def _safe_kurtosis(row):
    try:
        value = kurtosis(row, bias=False, nan_policy="omit")
    except Exception:
        value = 0.0
    value = np.asarray(value, dtype=np.float64)
    return float(np.nan_to_num(value, nan=0.0, posinf=0.0, neginf=0.0))


def _aggregate_7stats(frame_feature_matrix):
    x = np.asarray(frame_feature_matrix, dtype=np.float64)
    if x.ndim != 2 or x.shape[0] == 0:
        return np.zeros(0, dtype=np.float64)
    if x.shape[1] == 0:
        return np.zeros(x.shape[0] * 7, dtype=np.float64)

    parts = []
    for row in x:
        row = _nan_to_num_array(row)
        stats = [
            float(np.mean(row)),
            float(np.std(row)),
            float(np.min(row)),
            float(np.max(row)),
            float(np.median(row)),
            _safe_skew(row),
            _safe_kurtosis(row),
        ]
        parts.extend(stats)
    return _nan_to_num_array(parts)


def _aggregate_mean_std(frame_feature_matrix):
    x = np.asarray(frame_feature_matrix, dtype=np.float64)
    if x.ndim != 2 or x.shape[0] == 0:
        return np.zeros(0, dtype=np.float64)
    if x.shape[1] == 0:
        return np.zeros(x.shape[0] * 2, dtype=np.float64)

    parts = []
    for row in x:
        row = _nan_to_num_array(row)
        parts.extend([float(np.mean(row)), float(np.std(row))])
    return _nan_to_num_array(parts)


def _aggregate_f0_stats(f0_hz):
    f0 = _nan_to_num_array(f0_hz)
    voiced_fraction = float(np.mean(f0 != 0.0)) if f0.size else 0.0
    if f0.size == 0:
        return np.zeros(5, dtype=np.float64)
    stats = [
        float(np.mean(f0)),
        float(np.std(f0)),
        float(np.max(f0) - np.min(f0)),
        _safe_skew(f0),
        voiced_fraction,
    ]
    return _nan_to_num_array(stats)


def _aggregate_rms_stats(rms):
    e = _nan_to_num_array(rms)
    if e.size == 0:
        return np.zeros(4, dtype=np.float64)
    mean_e = float(np.mean(e))
    max_to_mean = float(np.max(e) / mean_e) if mean_e > 0.0 else 0.0
    stats = [
        mean_e,
        float(np.std(e)),
        float(np.max(e) - np.min(e)),
        max_to_mean,
    ]
    return _nan_to_num_array(stats)


def _extract_one(path):
    zero_vec = np.zeros(_EXPECTED_DIM, dtype=np.float64)
    try:
        y, sr = librosa.load(path, sr=None, mono=True)
        y = _nan_to_num_array(y)
        if y.size == 0:
            return zero_vec

        mfcc = librosa.feature.mfcc(y=y, sr=sr, n_mfcc=20)
        mfcc_feats = _aggregate_7stats(mfcc)

        contrast = librosa.feature.spectral_contrast(y=y, sr=sr)
        contrast_feats = _aggregate_mean_std(contrast)

        f0, _, _ = librosa.pyin(y, fmin=50.0, fmax=500.0)
        f0_feats = _aggregate_f0_stats(f0)

        rms = librosa.feature.rms(y=y)
        rms_feats = _aggregate_rms_stats(rms.ravel())

        feats = np.concatenate([mfcc_feats, contrast_feats, f0_feats, rms_feats], axis=0)
        feats = _nan_to_num_array(feats)
        if feats.shape[0] != _EXPECTED_DIM:
            fixed = np.zeros(_EXPECTED_DIM, dtype=np.float64)
            n = min(_EXPECTED_DIM, feats.shape[0])
            fixed[:n] = feats[:n]
            return fixed
        return feats
    except Exception:
        return zero_vec


def feature_fn(data_subset):
    features = [_extract_one(path) for path in data_subset]
    if len(features) == 0:
        return np.zeros((0, _EXPECTED_DIM), dtype=np.float64)
    X_subset = np.vstack(features).astype(np.float64, copy=False)
    X_subset = np.nan_to_num(X_subset, nan=0.0, posinf=0.0, neginf=0.0)
    return X_subset

