import numpy as np
import librosa

N_MFCC = 20
BASE_STATS = ("mean", "std", "min", "max", "median", "skew", "kurtosis")
DELTA_STATS = ("median", "min", "max")
FEATURE_DIM = N_MFCC * len(BASE_STATS) + N_MFCC * len(DELTA_STATS)
EPS = 1e-12


def _safe_moments_stats(matrix: np.ndarray) -> np.ndarray:
    matrix = np.asarray(matrix, dtype=np.float64)
    if matrix.ndim != 2 or matrix.shape[0] != N_MFCC:
        raise ValueError(f"Expected matrix shape ({N_MFCC}, frames), got {matrix.shape}")

    mean = np.mean(matrix, axis=1)
    std = np.std(matrix, axis=1)
    minv = np.min(matrix, axis=1)
    maxv = np.max(matrix, axis=1)
    median = np.median(matrix, axis=1)

    centered = matrix - mean[:, None]
    safe_std = np.where(std > EPS, std, 1.0)
    z = centered / safe_std[:, None]
    skew = np.mean(z ** 3, axis=1)
    kurtosis = np.mean(z ** 4, axis=1) - 3.0

    skew = np.where(std > EPS, skew, 0.0)
    kurtosis = np.where(std > EPS, kurtosis, 0.0)

    features = np.concatenate([mean, std, minv, maxv, median, skew, kurtosis], axis=0)
    return np.nan_to_num(features, nan=0.0, posinf=0.0, neginf=0.0)


def _safe_delta_stats(matrix: np.ndarray) -> np.ndarray:
    matrix = np.asarray(matrix, dtype=np.float64)
    median = np.median(matrix, axis=1)
    minv = np.min(matrix, axis=1)
    maxv = np.max(matrix, axis=1)
    features = np.concatenate([median, minv, maxv], axis=0)
    return np.nan_to_num(features, nan=0.0, posinf=0.0, neginf=0.0)


def _extract_one(audio_path: str) -> np.ndarray:
    try:
        y, sr = librosa.load(audio_path, sr=None, mono=True)
        y = np.asarray(y, dtype=np.float64)
        if y.size == 0:
            return np.zeros(FEATURE_DIM, dtype=np.float64)

        mfcc = librosa.feature.mfcc(y=y, sr=sr, n_mfcc=N_MFCC)
        if mfcc.ndim != 2 or mfcc.shape[0] != N_MFCC or mfcc.shape[1] == 0:
            return np.zeros(FEATURE_DIM, dtype=np.float64)

        base_features = _safe_moments_stats(mfcc)
        delta_mfcc = librosa.feature.delta(mfcc)
        delta_features = _safe_delta_stats(delta_mfcc)
        features = np.concatenate([base_features, delta_features], axis=0)

        if features.shape[0] != FEATURE_DIM:
            return np.zeros(FEATURE_DIM, dtype=np.float64)
        return np.nan_to_num(features, nan=0.0, posinf=0.0, neginf=0.0).astype(np.float64, copy=False)
    except Exception:
        return np.zeros(FEATURE_DIM, dtype=np.float64)


def feature_fn(data_subset):
    if len(data_subset) == 0:
        return np.empty((0, FEATURE_DIM), dtype=np.float64)

    rows = [_extract_one(path) for path in data_subset]
    X_subset = np.vstack(rows).astype(np.float64, copy=False)
    X_subset = np.nan_to_num(X_subset, nan=0.0, posinf=0.0, neginf=0.0)
    return X_subset

import numpy as np
import librosa


def _safe_moments(matrix: np.ndarray) -> np.ndarray:
    matrix = np.asarray(matrix, dtype=np.float64)
    if matrix.ndim != 2 or matrix.shape[1] == 0:
        return np.zeros((matrix.shape[0] if matrix.ndim == 2 else 0, 7), dtype=np.float64)

    mean = np.mean(matrix, axis=1)
    std = np.std(matrix, axis=1)
    min_ = np.min(matrix, axis=1)
    max_ = np.max(matrix, axis=1)
    median = np.median(matrix, axis=1)

    centered = matrix - mean[:, None]
    var = np.mean(centered ** 2, axis=1)
    safe_std = np.sqrt(np.maximum(var, 1e-12))
    skew = np.mean((centered / safe_std[:, None]) ** 3, axis=1)
    kurtosis = np.mean((centered / safe_std[:, None]) ** 4, axis=1) - 3.0

    stats = np.stack([mean, std, min_, max_, median, skew, kurtosis], axis=1)
    return np.nan_to_num(stats, nan=0.0, posinf=0.0, neginf=0.0)


