def _aggregate_mfcc(mfcc_matrix):
    mean = np.mean(mfcc_matrix, axis=1)
    std = np.std(mfcc_matrix, axis=1)
    min_ = np.min(mfcc_matrix, axis=1)
    max_ = np.max(mfcc_matrix, axis=1)
    median = np.median(mfcc_matrix, axis=1)
    kurt = kurtosis(mfcc_matrix, axis=1, fisher=True, bias=True)
