    return np.nan_to_num(feats, nan=0.0, posinf=0.0, neginf=0.0)


def _aggregate_spectral_contrast(sc_matrix):
    mean = np.mean(sc_matrix, axis=1)
    std = np.std(sc_matrix, axis=1)
    min_ = np.min(sc_matrix, axis=1)
    max_ = np.max(sc_matrix, axis=1)
    median = np.median(sc_matrix, axis=1)
    feats = np.concatenate([mean, std, min_, max_, median], axis=0)
