        sc_feats = _aggregate_spectral_contrast(sc)
        feats = np.concatenate([mfcc_feats, sc_feats], axis=0).astype(np.float64, copy=False)

        if feats.shape[0] != _OUTPUT_DIM:
            return np.zeros(_OUTPUT_DIM, dtype=np.float64)

        return np.nan_to_num(feats, nan=0.0, posinf=0.0, neginf=0.0)
