import numpy as np
import librosa
from scipy.stats import skew, kurtosis

_MFCC_DIM = 20
_MFCC_STATS = ("mean", "std", "min", "max", "median", "kurtosis")
_SC_STATS = ("mean", "std", "min", "max", "median", "skew", "kurtosis")
_EXPECTED_DIM = (_MFCC_DIM * len(_MFCC_STATS)) + (7 * len(_SC_STATS))


def _aggregate_rows(matrix, stat_names):
    matrix = np.asarray(matrix, dtype=np.float64)
    if matrix.ndim != 2 or matrix.shape[1] == 0:
        return np.zeros(matrix.shape[0] * len(stat_names), dtype=np.float64)

    features = []
    for stat_name in stat_names:
        if stat_name == "mean":
            values = np.mean(matrix, axis=1)
        elif stat_name == "std":
            values = np.std(matrix, axis=1)
        elif stat_name == "min":
            values = np.min(matrix, axis=1)
        elif stat_name == "max":
            values = np.max(matrix, axis=1)
        elif stat_name == "median":
            values = np.median(matrix, axis=1)
        elif stat_name == "skew":
            values = skew(matrix, axis=1, bias=False, nan_policy="omit")
        elif stat_name == "kurtosis":
            values = kurtosis(matrix, axis=1, fisher=True, bias=False, nan_policy="omit")
        else:
            raise ValueError(f"Unsupported statistic: {stat_name}")
        features.append(np.asarray(values, dtype=np.float64))

    return np.concatenate(features, axis=0)


def _extract_single(path):
    try:
        y, sr = librosa.load(path, sr=22050, mono=True)
        y = np.asarray(y, dtype=np.float64)
        if y.size == 0:
            raise ValueError("Empty audio signal")

        mfcc = librosa.feature.mfcc(y=y, sr=sr, n_mfcc=_MFCC_DIM)
        mfcc_features = _aggregate_rows(mfcc, _MFCC_STATS)

        spectral_contrast = librosa.feature.spectral_contrast(y=y, sr=sr)
        sc_features = _aggregate_rows(spectral_contrast, _SC_STATS)

        features = np.concatenate([mfcc_features, sc_features], axis=0)
        if features.shape[0] != _EXPECTED_DIM:
            raise ValueError(f"Unexpected feature dimension: {features.shape[0]}")

        return np.nan_to_num(features, nan=0.0, posinf=0.0, neginf=0.0)
    except Exception:
        return np.zeros(_EXPECTED_DIM, dtype=np.float64)


def feature_fn(data_subset):
    features = [_extract_single(path) for path in data_subset]
    if len(features) == 0:
        return np.zeros((0, _EXPECTED_DIM), dtype=np.float64)
    X_subset = np.vstack(features).astype(np.float64, copy=False)
    return np.nan_to_num(X_subset, nan=0.0, posinf=0.0, neginf=0.0)

import numpy as np
import librosa


def _safe_moments(x):
    x = np.asarray(x, dtype=np.float64)
    mean = float(np.mean(x))
    std = float(np.std(x))
    min_v = float(np.min(x))
    max_v = float(np.max(x))
    median = float(np.median(x))
    if std > 0.0:
        centered = (x - mean) / std
        skew = float(np.mean(centered ** 3))
        kurtosis = float(np.mean(centered ** 4) - 3.0)
    else:
        skew = 0.0
        kurtosis = 0.0
    return [mean, std, min_v, max_v, median, skew, kurtosis]


