import numpy as np
import librosa


def _ensure_min_length(y, min_length):
    if y.size >= min_length:
        return y
    return np.pad(y, (0, min_length - y.size), mode="constant")


def _aggregate_stats(matrix, stats):
    if matrix.ndim == 1:
        matrix = matrix[np.newaxis, :]
    feats = []
    for row in matrix:
        row = np.asarray(row, dtype=np.float64)
        if row.size == 0:
            feats.extend([0.0] * len(stats))
            continue
        for stat in stats:
            if stat == "mean":
                val = np.mean(row)
            elif stat == "std":
                val = np.std(row)
            elif stat == "min":
                val = np.min(row)
            elif stat == "max":
                val = np.max(row)
            elif stat == "median":
                val = np.median(row)
            elif stat == "p25":
                val = np.percentile(row, 25.0)
            elif stat == "p75":
                val = np.percentile(row, 75.0)
            else:
                raise ValueError(f"Unsupported stat: {stat}")
            feats.append(float(val))
    return np.asarray(feats, dtype=np.float64)


def _extract_sample_features(audio_path):
    target_dim = 179
    try:
        y, sr = librosa.load(audio_path, sr=None, mono=True)
        y = np.asarray(y, dtype=np.float64)
        if y.size == 0:
            return np.zeros(target_dim, dtype=np.float64)

        n_fft = 2048
        hop_length = 512
        y_proc = _ensure_min_length(y, n_fft)

        mfcc = librosa.feature.mfcc(y=y_proc, sr=sr, n_mfcc=20, n_fft=n_fft, hop_length=hop_length)
        mfcc_stats = _aggregate_stats(mfcc, ["mean", "std", "min", "max", "median", "p25", "p75"])

        spec_contrast = librosa.feature.spectral_contrast(
            y=y_proc,
            sr=sr,
            n_fft=n_fft,
            hop_length=hop_length,
            n_bands=6,
        )
        sc_stats = _aggregate_stats(spec_contrast, ["mean", "std", "min", "max", "median"])

        f0, _, _ = librosa.pyin(
            y_proc,
            sr=sr,
            fmin=librosa.note_to_hz("C2"),
            fmax=librosa.note_to_hz("C7"),
            frame_length=n_fft,
            hop_length=hop_length,
        )
        if f0 is None:
            voiced_stats = np.zeros(4, dtype=np.float64)
        else:
            f0 = np.asarray(f0, dtype=np.float64)
            voiced_mask = np.isfinite(f0) & (f0 > 0.0)
            voiced_fraction = float(np.mean(voiced_mask)) if f0.size > 0 else 0.0
            if np.any(voiced_mask):
                voiced_f0 = f0[voiced_mask]
                f0_mean = float(np.mean(voiced_f0))
                f0_std = float(np.std(voiced_f0))
                f0_range = float(np.max(voiced_f0) - np.min(voiced_f0))
                voiced_stats = np.asarray([f0_mean, f0_std, f0_range, voiced_fraction], dtype=np.float64)
            else:
                voiced_stats = np.asarray([0.0, 0.0, 0.0, 0.0], dtype=np.float64)

        features = np.concatenate([mfcc_stats, sc_stats, voiced_stats]).astype(np.float64, copy=False)
        if features.shape[0] != target_dim:
            fixed = np.zeros(target_dim, dtype=np.float64)
            n_copy = min(target_dim, features.shape[0])
            fixed[:n_copy] = features[:n_copy]
            features = fixed
        return np.nan_to_num(features, nan=0.0, posinf=0.0, neginf=0.0)
    except Exception:
        return np.zeros(target_dim, dtype=np.float64)


def feature_fn(data_subset):
    features = [_extract_sample_features(path) for path in data_subset]
    if not features:
        return np.zeros((0, 179), dtype=np.float64)
    X_subset = np.vstack(features).astype(np.float64, copy=False)
    return np.nan_to_num(X_subset, nan=0.0, posinf=0.0, neginf=0.0)

import numpy as np
import librosa
from scipy.stats import skew, kurtosis


def _safe_stats(values, include_higher=False):
    values = np.asarray(values, dtype=np.float64)
    if values.size == 0:
        return [0.0] * (7 if include_higher else 5)

    base_stats = [
        float(np.mean(values)),
        float(np.std(values)),
        float(np.min(values)),
        float(np.max(values)),
        float(np.median(values)),
    ]

    if include_higher:
        with np.errstate(all="ignore"):
            s = float(skew(values)) if values.size > 1 else 0.0
            k = float(kurtosis(values)) if values.size > 1 else 0.0
        if not np.isfinite(s):
            s = 0.0
        if not np.isfinite(k):
            k = 0.0
        base_stats.extend([s, k])

    return base_stats


def _extract_one(path):
    try:
        y, sr = librosa.load(path, sr=None, mono=True)
        y = np.asarray(y, dtype=np.float64)
        if y.size == 0:
            return np.zeros(145, dtype=np.float64)

        mfcc = librosa.feature.mfcc(y=y, sr=sr, n_mfcc=20)
        mfcc_features = []
        for i in range(mfcc.shape[0]):
            mfcc_features.extend(_safe_stats(mfcc[i], include_higher=True))

        zcr = librosa.feature.zero_crossing_rate(y=y)
        zcr_features = _safe_stats(zcr[0], include_higher=False)

        features = np.asarray(mfcc_features + zcr_features, dtype=np.float64)
        if features.shape[0] != 145:
            raise ValueError(f"Expected 145 features, got {features.shape[0]}")
        return np.nan_to_num(features, nan=0.0, posinf=0.0, neginf=0.0)
    except Exception:
        return np.zeros(145, dtype=np.float64)


def feature_fn(data_subset):
    features = [_extract_one(path) for path in data_subset]
    if len(features) == 0:
        return np.zeros((0, 145), dtype=np.float64)
    X_subset = np.vstack(features).astype(np.float64, copy=False)
    return np.nan_to_num(X_subset, nan=0.0, posinf=0.0, neginf=0.0)

import numpy as np
import librosa

_MFCC_COUNT = 20
_SC_BANDS = 7
_STATS_PER_BAND = 5
_SR = 22050
_N_FFT = 2048
_HOP_LENGTH = 512
_FEATURE_DIM = (_MFCC_COUNT * _STATS_PER_BAND) + (_SC_BANDS * _STATS_PER_BAND)


def _aggregate_feature_matrix(mat: np.ndarray) -> np.ndarray:
    mat = np.asarray(mat, dtype=np.float64)
    if mat.ndim != 2 or mat.shape[1] == 0:
        return np.zeros(mat.shape[0] * _STATS_PER_BAND, dtype=np.float64)
    stats = np.column_stack([
        np.mean(mat, axis=1),
        np.std(mat, axis=1),
        np.min(mat, axis=1),
        np.max(mat, axis=1),
        np.median(mat, axis=1),
    ])
    return np.nan_to_num(stats, nan=0.0, posinf=0.0, neginf=0.0).reshape(-1)


def _extract_single(path: str) -> np.ndarray:
    try:
        y, sr = librosa.load(path, sr=_SR, mono=True)
        if y.size == 0:
            return np.zeros(_FEATURE_DIM, dtype=np.float64)

        mfcc = librosa.feature.mfcc(
            y=y,
            sr=sr,
            n_mfcc=_MFCC_COUNT,
            n_fft=_N_FFT,
            hop_length=_HOP_LENGTH,
        )
        spectral_contrast = librosa.feature.spectral_contrast(
            y=y,
            sr=sr,
            n_fft=_N_FFT,
            hop_length=_HOP_LENGTH,
        )

        mfcc_features = _aggregate_feature_matrix(mfcc)
        sc_features = _aggregate_feature_matrix(spectral_contrast)
        features = np.concatenate([mfcc_features, sc_features]).astype(np.float64, copy=False)

        if features.shape[0] != _FEATURE_DIM:
            fixed = np.zeros(_FEATURE_DIM, dtype=np.float64)
            fixed[: min(_FEATURE_DIM, features.shape[0])] = features[:_FEATURE_DIM]
            features = fixed

        return np.nan_to_num(features, nan=0.0, posinf=0.0, neginf=0.0)
    except Exception:
        return np.zeros(_FEATURE_DIM, dtype=np.float64)


def feature_fn(data_subset):
    features = [_extract_single(path) for path in data_subset]
    if not features:
        return np.zeros((0, _FEATURE_DIM), dtype=np.float64)
    X_subset = np.vstack(features).astype(np.float64, copy=False)
    return np.nan_to_num(X_subset, nan=0.0, posinf=0.0, neginf=0.0)

import numpy as np
import librosa
from scipy.stats import skew, kurtosis


def _safe_row_stats(row, stat_names):
    row = np.asarray(row, dtype=np.float64)
    values = []
    is_constant = row.size == 0 or np.allclose(row, row[0] if row.size else 0.0)

    for name in stat_names:
        if name == "mean":
            v = np.mean(row) if row.size else 0.0
        elif name == "std":
            v = np.std(row) if row.size else 0.0
        elif name == "min":
            v = np.min(row) if row.size else 0.0
        elif name == "max":
            v = np.max(row) if row.size else 0.0
        elif name == "median":
            v = np.median(row) if row.size else 0.0
        elif name == "skew":
            v = 0.0 if is_constant else float(skew(row, bias=True))
        elif name == "kurtosis":
            v = 0.0 if is_constant else float(kurtosis(row, fisher=True, bias=True))
        else:
            raise ValueError(f"Unsupported statistic: {name}")
        values.append(v)

    return np.asarray(values, dtype=np.float64)


def _aggregate_feature_matrix(feature_matrix, stat_names):
    feature_matrix = np.asarray(feature_matrix, dtype=np.float64)
    aggregated = [_safe_row_stats(feature_matrix[i], stat_names) for i in range(feature_matrix.shape[0])]
    return np.concatenate(aggregated, axis=0)


def _extract_single_audio_features(audio_path):
    expected_dim = 161
    try:
        y, sr = librosa.load(audio_path, sr=22050, mono=True)
        if y.size == 0:
            return np.zeros(expected_dim, dtype=np.float64)

        mfcc = librosa.feature.mfcc(y=y, sr=sr, n_mfcc=20)
        mfcc_stats = _aggregate_feature_matrix(
            mfcc,
            ["mean", "std", "min", "max", "median", "skew", "kurtosis"],
        )

        spectral_contrast = librosa.feature.spectral_contrast(y=y, sr=sr)
        sc_stats = _aggregate_feature_matrix(
            spectral_contrast,
            ["mean", "std", "median"],
        )

        features = np.concatenate([mfcc_stats, sc_stats], axis=0)
        if features.shape[0] != expected_dim:
            raise ValueError(f"Unexpected feature dimension {features.shape[0]} != {expected_dim}")

        return np.nan_to_num(features, nan=0.0, posinf=0.0, neginf=0.0).astype(np.float64, copy=False)
    except Exception:
        return np.zeros(expected_dim, dtype=np.float64)


def feature_fn(data_subset):
    features = [_extract_single_audio_features(audio_path) for audio_path in data_subset]
    if len(features) == 0:
        return np.zeros((0, 161), dtype=np.float64)
    X_subset = np.vstack(features).astype(np.float64, copy=False)
    return np.nan_to_num(X_subset, nan=0.0, posinf=0.0, neginf=0.0)

import numpy as np
import librosa
from scipy.stats import skew, kurtosis


def _finite_stat(value):
    value = float(value)
    if not np.isfinite(value):
        return 0.0
    return value


def _aggregate_vector(x):
    x = np.asarray(x, dtype=np.float64).ravel()
    if x.size == 0:
        return [0.0] * 7
    return [
        _finite_stat(np.mean(x)),
        _finite_stat(np.std(x)),
        _finite_stat(np.min(x)),
        _finite_stat(np.max(x)),
        _finite_stat(np.median(x)),
        _finite_stat(skew(x)),
        _finite_stat(kurtosis(x)),
    ]


def _aggregate_flatness(x):
    x = np.asarray(x, dtype=np.float64).ravel()
    if x.size == 0:
        return [0.0] * 5
    return [
        _finite_stat(np.mean(x)),
        _finite_stat(np.std(x)),
        _finite_stat(np.min(x)),
        _finite_stat(np.max(x)),
        _finite_stat(np.median(x)),
    ]


def _extract_one(path):
    try:
        y, sr = librosa.load(path, sr=22050, mono=True)
        if y.size == 0:
            return np.zeros(145, dtype=np.float64)

        mfcc = librosa.feature.mfcc(y=y, sr=sr, n_mfcc=20)
        mfcc_features = []
        for i in range(mfcc.shape[0]):
            mfcc_features.extend(_aggregate_vector(mfcc[i]))

        flatness = librosa.feature.spectral_flatness(y=y)
        flatness_features = _aggregate_flatness(flatness.ravel())

        features = np.asarray(mfcc_features + flatness_features, dtype=np.float64)
        if features.shape[0] != 145:
            fixed = np.zeros(145, dtype=np.float64)
            fixed[: min(145, features.shape[0])] = features[:145]
            features = fixed
        return np.nan_to_num(features, nan=0.0, posinf=0.0, neginf=0.0)
    except Exception:
        return np.zeros(145, dtype=np.float64)


def feature_fn(data_subset):
    features = [_extract_one(path) for path in data_subset]
    if len(features) == 0:
        return np.zeros((0, 145), dtype=np.float64)
    X_subset = np.vstack(features).astype(np.float64, copy=False)
    X_subset = np.nan_to_num(X_subset, nan=0.0, posinf=0.0, neginf=0.0)
    return X_subset

import numpy as np
import librosa


_DEFAULT_SR = 22050
_DEFAULT_N_FFT = 2048
_DEFAULT_HOP_LENGTH = 512
_EPS = 1e-12


def _safe_mono_load(path):
    try:
        y, sr = librosa.load(path, sr=_DEFAULT_SR, mono=True)
        if y is None or y.size == 0:
            return np.zeros(1, dtype=np.float64), _DEFAULT_SR
        y = np.asarray(y, dtype=np.float64)
        if not np.all(np.isfinite(y)):
            y = np.nan_to_num(y, nan=0.0, posinf=0.0, neginf=0.0)
        return y, sr
    except Exception:
        return np.zeros(1, dtype=np.float64), _DEFAULT_SR


def _skew(x):
    x = np.asarray(x, dtype=np.float64)
    if x.size == 0:
        return 0.0
    mu = np.mean(x)
    sigma = np.std(x)
    if sigma < _EPS:
        return 0.0
    z = (x - mu) / sigma
    return float(np.mean(z ** 3))


def _kurtosis_excess(x):
    x = np.asarray(x, dtype=np.float64)
    if x.size == 0:
        return 0.0
    mu = np.mean(x)
    sigma = np.std(x)
    if sigma < _EPS:
        return 0.0
    z = (x - mu) / sigma
    return float(np.mean(z ** 4) - 3.0)


def _aggregate_1d(x, stats):
    x = np.asarray(x, dtype=np.float64).reshape(-1)
    if x.size == 0:
        x = np.zeros(1, dtype=np.float64)
    values = []
    for stat in stats:
        if stat == "mean":
            values.append(float(np.mean(x)))
        elif stat == "std":
            values.append(float(np.std(x)))
        elif stat == "min":
            values.append(float(np.min(x)))
        elif stat == "max":
            values.append(float(np.max(x)))
        elif stat == "median":
            values.append(float(np.median(x)))
        elif stat == "skew":
            values.append(_skew(x))
        elif stat == "kurtosis":
            values.append(_kurtosis_excess(x))
        else:
            raise ValueError(f"Unsupported stat: {stat}")
    out = np.asarray(values, dtype=np.float64)
    return np.nan_to_num(out, nan=0.0, posinf=0.0, neginf=0.0)


def _mfcc_7stat_features(y, sr):
    mfcc = librosa.feature.mfcc(
        y=y,
        sr=sr,
        n_mfcc=20,
        n_fft=_DEFAULT_N_FFT,
        hop_length=_DEFAULT_HOP_LENGTH,
    )
    mfcc = np.asarray(mfcc, dtype=np.float64)
    stats = ["mean", "std", "min", "max", "median", "skew", "kurtosis"]
    feat = [_aggregate_1d(mfcc[i], stats) for i in range(mfcc.shape[0])]
    return np.concatenate(feat, axis=0)


def _rolloff_5stat_features(y, sr):
    rolloff = librosa.feature.spectral_rolloff(
        y=y,
        sr=sr,
        n_fft=_DEFAULT_N_FFT,
        hop_length=_DEFAULT_HOP_LENGTH,
        roll_percent=0.85,
    )
    rolloff = np.asarray(rolloff, dtype=np.float64).reshape(-1)
    stats = ["mean", "std", "min", "max", "median"]
    return _aggregate_1d(rolloff, stats)


def feature_fn(data_subset):
    features = []
    for path in data_subset:
        y, sr = _safe_mono_load(path)
        mfcc_feat = _mfcc_7stat_features(y, sr)
        rolloff_feat = _rolloff_5stat_features(y, sr)
        feat = np.concatenate([mfcc_feat, rolloff_feat], axis=0)
        feat = np.nan_to_num(feat, nan=0.0, posinf=0.0, neginf=0.0)
        if feat.shape[0] != 145:
            raise ValueError(f"Expected 145 features, got {feat.shape[0]} for sample: {path}")
        features.append(feat)
    if not features:
        return np.zeros((0, 145), dtype=np.float64)
    X_subset = np.vstack(features).astype(np.float64, copy=False)
    X_subset = np.nan_to_num(X_subset, nan=0.0, posinf=0.0, neginf=0.0)
    return X_subset

import numpy as np
import librosa


def _safe_kurtosis(x, axis=1):
    x = np.asarray(x, dtype=np.float64)
    if x.ndim != 2:
        raise ValueError("_safe_kurtosis expects a 2D array")
    n = x.shape[axis]
    if n < 2:
        out_shape = list(x.shape)
        del out_shape[axis]
        return np.zeros(out_shape, dtype=np.float64)
    mean = np.mean(x, axis=axis, keepdims=True)
    centered = x - mean
    m2 = np.mean(centered ** 2, axis=axis)
    m4 = np.mean(centered ** 4, axis=axis)
    kurt = np.zeros_like(m2, dtype=np.float64)
    mask = m2 > 0.0
    kurt[mask] = (m4[mask] / (m2[mask] ** 2)) - 3.0
    return kurt


def _aggregate_stats(matrix, include_kurtosis=False):
    matrix = np.asarray(matrix, dtype=np.float64)
    if matrix.ndim != 2:
        raise ValueError("Expected a 2D feature matrix")
    stats = [
        np.mean(matrix, axis=1),
        np.std(matrix, axis=1),
        np.min(matrix, axis=1),
        np.max(matrix, axis=1),
        np.median(matrix, axis=1),
    ]
    if include_kurtosis:
        stats.append(_safe_kurtosis(matrix, axis=1))
    return np.concatenate(stats, axis=0)


def _extract_single(path):
    target_dim = 157
    try:
        y, sr = librosa.load(path, sr=None, mono=True)
        y = np.asarray(y, dtype=np.float64)
        if y.size == 0:
            return np.zeros(target_dim, dtype=np.float64)

        mfcc = librosa.feature.mfcc(y=y, sr=sr, n_mfcc=20)
        mfcc_stats = _aggregate_stats(mfcc, include_kurtosis=True)

        spectral_contrast = librosa.feature.spectral_contrast(y=y, sr=sr)
        sc_stats = _aggregate_stats(spectral_contrast, include_kurtosis=False)

        flatness = librosa.feature.spectral_flatness(y=y)
        flatness_stats = np.array(
            [np.mean(flatness, axis=1)[0], np.std(flatness, axis=1)[0]],
            dtype=np.float64,
        )

        features = np.concatenate([mfcc_stats, sc_stats, flatness_stats], axis=0)
        if features.shape[0] != target_dim:
            raise ValueError(f"Expected {target_dim} features, got {features.shape[0]}")
        return np.nan_to_num(features, nan=0.0, posinf=0.0, neginf=0.0)
    except Exception:
        return np.zeros(target_dim, dtype=np.float64)


def feature_fn(data_subset):
    features = [_extract_single(path) for path in data_subset]
    if len(features) == 0:
        return np.zeros((0, 157), dtype=np.float64)
    return np.vstack(features).astype(np.float64, copy=False)

import numpy as np
import librosa


def _aggregate_seven_stats(matrix: np.ndarray) -> np.ndarray:
    stats = [
        np.mean(matrix, axis=1),
        np.std(matrix, axis=1),
        np.median(matrix, axis=1),
        np.min(matrix, axis=1),
        np.max(matrix, axis=1),
        np.percentile(matrix, 25, axis=1),
        np.percentile(matrix, 75, axis=1),
    ]
    return np.concatenate(stats, axis=0).astype(np.float64, copy=False)


def _aggregate_three_stats(matrix: np.ndarray) -> np.ndarray:
    stats = [
        np.mean(matrix, axis=1),
        np.std(matrix, axis=1),
        np.median(matrix, axis=1),
    ]
    return np.concatenate(stats, axis=0).astype(np.float64, copy=False)


def _extract_one(audio_path: str) -> np.ndarray:
    y, sr = librosa.load(audio_path, sr=22050, mono=True)

    mfcc = librosa.feature.mfcc(y=y, sr=sr, n_mfcc=20)
    mfcc_features = _aggregate_seven_stats(mfcc)

    mel = librosa.feature.melspectrogram(y=y, sr=sr, n_fft=2048, hop_length=512, n_mels=8)
    mel_db = librosa.power_to_db(mel)
    mel_features = _aggregate_three_stats(mel_db)

    features = np.concatenate([mfcc_features, mel_features], axis=0)
    if features.shape[0] != 164:
        raise ValueError(f"Expected 164 features, got {features.shape[0]}")
    return np.nan_to_num(features, nan=0.0, posinf=0.0, neginf=0.0)


def feature_fn(data_subset):
    if not isinstance(data_subset, list):
        raise TypeError("data_subset must be a list of audio file paths")

    all_features = []
    for audio_path in data_subset:
        try:
            features = _extract_one(audio_path)
        except Exception:
            features = np.zeros(164, dtype=np.float64)
        all_features.append(features)

    if not all_features:
        return np.empty((0, 164), dtype=np.float64)

    X_subset = np.vstack(all_features).astype(np.float64, copy=False)
    X_subset = np.nan_to_num(X_subset, nan=0.0, posinf=0.0, neginf=0.0)
    return X_subset

import numpy as np
import librosa
from scipy.stats import skew, kurtosis


TARGET_SR = 22050
N_MFCC = 20
N_FFT = 2048
HOP_LENGTH = 512
SC_N_BANDS = 6
SC_FMIN = 200.0
MFCC_STATS = ("mean", "std", "min", "max", "median", "skew", "kurtosis")
