def _sanitize_vector(vec, expected_dim):
    vec = np.asarray(vec, dtype=np.float64).reshape(-1)
    if vec.size != expected_dim:
        if vec.size < expected_dim:
            vec = np.pad(vec, (0, expected_dim - vec.size), mode="constant")
        else:
            vec = vec[:expected_dim]
    return np.nan_to_num(vec, nan=0.0, posinf=0.0, neginf=0.0)


def _aggregate_rows(x, stats_to_use):
    x = np.asarray(x, dtype=np.float64)
    if x.ndim != 2:
        raise ValueError("Expected a 2D array with shape (n_features, n_frames).")
    if x.shape[1] == 0:
        x = np.zeros((x.shape[0], 1), dtype=np.float64)

    parts = []
    for stat_name in stats_to_use:
        if stat_name == "mean":
            vals = np.mean(x, axis=1)
        elif stat_name == "std":
            vals = np.std(x, axis=1)
        elif stat_name == "min":
