import numpy as np
import librosa
from scipy.stats import skew, kurtosis


def _safe_stat_moments(x):
    x = np.asarray(x, dtype=np.float64)
    if x.size == 0:
        return 0.0, 0.0
    if np.allclose(x, x[0]):
        return 0.0, 0.0
    sk = float(skew(x, bias=False, nan_policy="omit"))
    ku = float(kurtosis(x, bias=False, fisher=True, nan_policy="omit"))
    if not np.isfinite(sk):
        sk = 0.0
    if not np.isfinite(ku):
        ku = 0.0
    return sk, ku


def _aggregate_mfcc(mfcc):
    feats = []
    for coeff in mfcc:
        coeff = np.asarray(coeff, dtype=np.float64)
        if coeff.size == 0:
            feats.extend([0.0] * 7)
            continue
        sk, ku = _safe_stat_moments(coeff)
        feats.extend([
            float(np.mean(coeff)),
            float(np.std(coeff)),
            float(np.min(coeff)),
            float(np.max(coeff)),
            float(np.median(coeff)),
            sk,
            ku,
        ])
    return feats


def _aggregate_sc(sc):
    feats = []
    for band in sc:
        band = np.asarray(band, dtype=np.float64)
        if band.size == 0:
            feats.extend([0.0] * 5)
            continue
        feats.extend([
            float(np.mean(band)),
            float(np.std(band)),
            float(np.min(band)),
            float(np.max(band)),
            float(np.median(band)),
        ])
    return feats


