        feats = np.asarray(feats, dtype=np.float64)
        if feats.shape[0] != 175:
            fixed = np.zeros(175, dtype=np.float64)
            fixed[: min(175, feats.shape[0])] = feats[:175]
            feats = fixed
    except Exception:
        feats = np.zeros(175, dtype=np.float64)
    return np.nan_to_num(feats, nan=0.0, posinf=0.0, neginf=0.0)


