def _aggregate_with_kurtosis(matrix: np.ndarray) -> np.ndarray:
    if matrix.ndim != 2:
        raise ValueError("Expected a 2D feature matrix with shape (n_features, n_frames).")
    if matrix.shape[1] == 0:
        return np.zeros(matrix.shape[0] * 6, dtype=np.float64)

    mean = np.mean(matrix, axis=1)
