    min_ = np.min(matrix, axis=1)
    max_ = np.max(matrix, axis=1)
    median = np.median(matrix, axis=1)
    kurt = kurtosis(matrix, axis=1, fisher=True, bias=False, nan_policy="omit")

    features = np.concatenate([mean, std, min_, max_, median, kurt]).astype(np.float64, copy=False)
    return np.nan_to_num(features, nan=0.0, posinf=0.0, neginf=0.0)


def _aggregate_basic(matrix: np.ndarray) -> np.ndarray:
    if matrix.ndim != 2:
        raise ValueError("Expected a 2D feature matrix with shape (n_features, n_frames).")
    if matrix.shape[1] == 0:
