import numpy as np
import librosa


def _safe_kurtosis(values: np.ndarray) -> float:
    values = np.asarray(values, dtype=np.float64)
    if values.size == 0:
        return 0.0
    mean = float(np.mean(values))
    centered = values - mean
    var = float(np.mean(centered ** 2))
    if var <= 1e-20:
        return 0.0
    fourth = float(np.mean(centered ** 4))
    return fourth / (var ** 2) - 3.0


def _aggregate_rows(matrix: np.ndarray, include_kurtosis: bool) -> np.ndarray:
    matrix = np.asarray(matrix, dtype=np.float64)
    features = []
    for row in matrix:
        stats = [
            float(np.mean(row)),
            float(np.std(row)),
            float(np.min(row)),
            float(np.max(row)),
            float(np.median(row)),
        ]
        if include_kurtosis:
            stats.append(_safe_kurtosis(row))
        else:
            stats[-2:] = [float(np.median(row)), float(np.min(row))]
        features.extend(stats)
    return np.asarray(features, dtype=np.float64)


