_SPECTRAL_CONTRAST_BANDS = 7
_SPECTRAL_CONTRAST_STATS_PER_BAND = 5
_EXPECTED_DIM = (_MFCC_DIM * _MFCC_STATS_PER_COEFF) + (_SPECTRAL_CONTRAST_BANDS * _SPECTRAL_CONTRAST_STATS_PER_BAND)


def _safe_kurtosis(x: np.ndarray) -> float:
    x = np.asarray(x, dtype=np.float64)
    if x.size < 2:
        return 0.0
    if np.allclose(x, x[0]):
        return 0.0
    value = kurtosis(x, fisher=True, bias=True, nan_policy="omit")
    if not np.isfinite(value):
        return 0.0
    return float(value)


def _aggregate_mfcc(mfcc: np.ndarray) -> np.ndarray:
    feats = []
    for coeff in mfcc:
        coeff = np.asarray(coeff, dtype=np.float64)
        feats.extend([
            float(np.mean(coeff)),
            float(np.std(coeff)),
            float(np.percentile(coeff, 10)),
            float(np.percentile(coeff, 90)),
            float(np.median(coeff)),
            _safe_kurtosis(coeff),
        ])
    return np.asarray(feats, dtype=np.float64)


def _aggregate_spectral_contrast(contrast: np.ndarray) -> np.ndarray:
    feats = []
    for band in contrast:
        band = np.asarray(band, dtype=np.float64)
        feats.extend([
            float(np.mean(band)),
            float(np.std(band)),
            float(np.min(band)),
            float(np.max(band)),
            float(np.median(band)),
        ])
    return np.asarray(feats, dtype=np.float64)


