        if contrast.shape[0] != _SPECTRAL_CONTRAST_BANDS:
            return zero_vec.copy()

        mfcc_feats = _aggregate_mfcc(mfcc)
        contrast_feats = _aggregate_spectral_contrast(contrast)
        feat = np.concatenate([mfcc_feats, contrast_feats], axis=0)

        if feat.shape[0] != _EXPECTED_DIM:
            return zero_vec.copy()

        feat = np.nan_to_num(feat, nan=0.0, posinf=0.0, neginf=0.0)
        return feat.astype(np.float64, copy=False)
    except Exception:
        return zero_vec.copy()


def feature_fn(data_subset):
    features = [_extract_single(path) for path in data_subset]
