    mean = np.mean(frame_matrix, axis=1)
    std = np.std(frame_matrix, axis=1)
    centered = frame_matrix - mean[:, None]
    with np.errstate(divide="ignore", invalid="ignore"):
        kurt = np.mean((centered / std[:, None]) ** 4, axis=1) - 3.0
    kurt = np.where(std > 0, kurt, 0.0)
    return np.nan_to_num(kurt, nan=0.0, posinf=0.0, neginf=0.0)


