import numpy as np
import librosa


def _safe_kurtosis(frame_matrix):
    frame_matrix = np.asarray(frame_matrix, dtype=np.float64)
    mean = np.mean(frame_matrix, axis=1, keepdims=True)
    centered = frame_matrix - mean
    m2 = np.mean(centered ** 2, axis=1)
    m4 = np.mean(centered ** 4, axis=1)
    out = np.zeros(frame_matrix.shape[0], dtype=np.float64)
    nonzero = m2 > 0
    out[nonzero] = m4[nonzero] / (m2[nonzero] ** 2)
    return out


def _aggregate_stats(frame_matrix, include_range=True, include_kurtosis=True):
    frame_matrix = np.asarray(frame_matrix, dtype=np.float64)
    stats = [
        np.mean(frame_matrix, axis=1),
        np.std(frame_matrix, axis=1),
        np.min(frame_matrix, axis=1),
        np.max(frame_matrix, axis=1),
        np.median(frame_matrix, axis=1),
    ]
    if include_kurtosis:
        stats.append(_safe_kurtosis(frame_matrix))
    if include_range:
        stats.append(np.max(frame_matrix, axis=1) - np.min(frame_matrix, axis=1))
    return np.concatenate(stats, axis=0)


def _extract_single(path):
