                np.median(spectral_contrast, axis=1),
                np.min(spectral_contrast, axis=1),
            ], axis=0)
    except Exception:
        pass

    features = np.concatenate([mfcc_features, sc_features], axis=0)
    features = np.nan_to_num(features, nan=0.0, posinf=0.0, neginf=0.0)
