import numpy as np
import librosa


def _safe_kurtosis(x: np.ndarray) -> float:
    x = np.asarray(x, dtype=np.float64)
    if x.size == 0:
        return 0.0
    mean = np.mean(x)
    centered = x - mean
    var = np.mean(centered ** 2)
    if var <= 1e-18:
        return 0.0
    fourth = np.mean(centered ** 4)
    return float(fourth / (var ** 2) - 3.0)


def _summarize_rows(mat: np.ndarray, stats: tuple[str, ...]) -> np.ndarray:
    mat = np.asarray(mat, dtype=np.float64)
    feats = []
    for row in mat:
        for stat in stats:
            if stat == "mean":
                feats.append(float(np.mean(row)))
            elif stat == "std":
                feats.append(float(np.std(row)))
            elif stat == "min":
                feats.append(float(np.min(row)))
            elif stat == "max":
                feats.append(float(np.max(row)))
            elif stat == "median":
                feats.append(float(np.median(row)))
            elif stat == "kurtosis":
                feats.append(_safe_kurtosis(row))
            else:
                raise ValueError(f"Unsupported stat: {stat}")
    return np.asarray(feats, dtype=np.float64)


def _extract_single(path: str) -> np.ndarray:
    mfcc_dim = 21 * 6
    sc_dim = 7 * 3
    total_dim = mfcc_dim + sc_dim
    try:
        y, sr = librosa.load(path, sr=None, mono=True)
        y = np.asarray(y, dtype=np.float64)
        if y.size == 0:
            return np.zeros(total_dim, dtype=np.float64)
        if y.size < 2:
            y = np.pad(y, (0, 2 - y.size), mode="constant")

        mfcc = librosa.feature.mfcc(y=y, sr=sr, n_mfcc=21)
        sc = librosa.feature.spectral_contrast(y=y, sr=sr, n_bands=6)

        mfcc_feats = _summarize_rows(mfcc, ("mean", "std", "min", "max", "median", "kurtosis"))
        sc_feats = _summarize_rows(sc, ("mean", "std", "min"))

        feats = np.concatenate([mfcc_feats, sc_feats]).astype(np.float64, copy=False)
        if feats.shape[0] != total_dim:
            fixed = np.zeros(total_dim, dtype=np.float64)
            fixed[: min(total_dim, feats.shape[0])] = feats[:total_dim]
            feats = fixed
        feats = np.nan_to_num(feats, nan=0.0, posinf=0.0, neginf=0.0)
        return feats
    except Exception:
        return np.zeros(total_dim, dtype=np.float64)


def feature_fn(data_subset):
