    return X_subset

import numpy as np
import librosa
from scipy.stats import kurtosis


def _safe_stat_summary(matrix, stats_order):
    if matrix.ndim == 1:
        matrix = matrix[np.newaxis, :]
    if matrix.shape[1] == 0:
        matrix = np.zeros((matrix.shape[0], 1), dtype=np.float64)
    matrix = np.nan_to_num(matrix.astype(np.float64, copy=False), nan=0.0, posinf=0.0, neginf=0.0)
    features = []
    for stat_name in stats_order:
        if stat_name == "mean":
            values = np.mean(matrix, axis=1)
        elif stat_name == "std":
            values = np.std(matrix, axis=1)
        elif stat_name == "min":
            values = np.min(matrix, axis=1)
        elif stat_name == "max":
            values = np.max(matrix, axis=1)
        elif stat_name == "median":
            values = np.median(matrix, axis=1)
        elif stat_name == "kurtosis":
            values = kurtosis(matrix, axis=1, fisher=True, bias=False, nan_policy="omit")
        else:
            raise ValueError(f"Unsupported statistic: {stat_name}")
        values = np.nan_to_num(values.astype(np.float64, copy=False), nan=0.0, posinf=0.0, neginf=0.0)
        features.append(values)
    return np.concatenate(features, axis=0)


def _frame_hnr(y, sr, frame_length=2048, hop_length=512, fmin=50.0, fmax=500.0):
    if y.size == 0:
        return np.zeros(1, dtype=np.float64)
    if y.size < frame_length:
        y = np.pad(y, (0, frame_length - y.size), mode="constant")
    frames = librosa.util.frame(y, frame_length=frame_length, hop_length=hop_length)
    window = np.hanning(frame_length).astype(np.float64)
    frames = frames.astype(np.float64, copy=False) * window[:, np.newaxis]

    min_lag = max(1, int(sr / fmax))
    max_lag = min(frame_length - 1, int(sr / fmin))
    hnr_values = np.empty(frames.shape[1], dtype=np.float64)

    for i in range(frames.shape[1]):
        frame = frames[:, i]
        energy = np.dot(frame, frame)
        if not np.isfinite(energy) or energy <= 1e-12 or min_lag > max_lag:
            hnr_values[i] = np.nan
            continue
        autocorr = np.correlate(frame, frame, mode="full")[frame_length - 1:]
        autocorr = autocorr / (autocorr[0] + 1e-12)
        peak = np.max(autocorr[min_lag:max_lag + 1])
        if not np.isfinite(peak) or peak <= 0.0 or peak >= 1.0:
            hnr_values[i] = np.nan
            continue
        hnr_values[i] = 10.0 * np.log10(peak / (1.0 - peak))

    return np.nan_to_num(hnr_values, nan=0.0, posinf=0.0, neginf=0.0)


def _extract_features_from_path(path):
    target_dim = 158
    try:
        y, sr = librosa.load(path, sr=None, mono=True)
        y = np.nan_to_num(y.astype(np.float64, copy=False), nan=0.0, posinf=0.0, neginf=0.0)
        if y.size == 0:
            return np.zeros(target_dim, dtype=np.float64)

        mfcc = librosa.feature.mfcc(y=y, sr=sr, n_mfcc=21, n_fft=2048, hop_length=512, center=False)
        mfcc_feats = _safe_stat_summary(mfcc, ["mean", "std", "min", "max", "median", "kurtosis"])

        spectral_contrast = librosa.feature.spectral_contrast(y=y, sr=sr, n_fft=2048, hop_length=512, center=False)
        sc_feats = _safe_stat_summary(spectral_contrast, ["mean", "std", "median", "min"])

        hnr_frames = _frame_hnr(y=y, sr=sr, frame_length=2048, hop_length=512, fmin=50.0, fmax=500.0)
        hnr_feats = _safe_stat_summary(hnr_frames, ["mean", "std", "min", "kurtosis"])

        feats = np.concatenate([mfcc_feats, sc_feats, hnr_feats], axis=0)
        if feats.shape[0] != target_dim:
            fixed = np.zeros(target_dim, dtype=np.float64)
            fixed[: min(target_dim, feats.shape[0])] = feats[:target_dim]
            feats = fixed
        return np.nan_to_num(feats.astype(np.float64, copy=False), nan=0.0, posinf=0.0, neginf=0.0)
    except Exception:
        return np.zeros(target_dim, dtype=np.float64)


def feature_fn(data_subset):
    features = [_extract_features_from_path(path) for path in data_subset]
    if len(features) == 0:
        return np.zeros((0, 158), dtype=np.float64)
    X_subset = np.vstack(features).astype(np.float64, copy=False)
    return np.nan_to_num(X_subset, nan=0.0, posinf=0.0, neginf=0.0)

import numpy as np
import librosa


def _safe_kurtosis(x: np.ndarray) -> np.ndarray:
    x = np.asarray(x, dtype=np.float64)
    if x.ndim == 1:
        x = x[np.newaxis, :]
    means = np.mean(x, axis=1, keepdims=True)
    centered = x - means
    var = np.mean(centered ** 2, axis=1)
    fourth = np.mean(centered ** 4, axis=1)
    kurt = np.zeros(x.shape[0], dtype=np.float64)
    valid = var > 1e-12
    kurt[valid] = fourth[valid] / (var[valid] ** 2) - 3.0
    return kurt


def _aggregate_matrix_stats(mat: np.ndarray, stats: tuple[str, ...]) -> np.ndarray:
    mat = np.asarray(mat, dtype=np.float64)
    parts = []
    for stat in stats:
        if stat == "mean":
            parts.append(np.mean(mat, axis=1))
        elif stat == "std":
            parts.append(np.std(mat, axis=1))
        elif stat == "min":
            parts.append(np.min(mat, axis=1))
        elif stat == "max":
            parts.append(np.max(mat, axis=1))
        elif stat == "median":
            parts.append(np.median(mat, axis=1))
        elif stat == "kurtosis":
            parts.append(_safe_kurtosis(mat))
        else:
            raise ValueError(f"Unsupported stat: {stat}")
    return np.concatenate(parts, axis=0).astype(np.float64, copy=False)


def _aggregate_vector_stats(vec: np.ndarray, stats: tuple[str, ...]) -> np.ndarray:
    vec = np.asarray(vec, dtype=np.float64).reshape(-1)
    parts = []
    for stat in stats:
        if stat == "mean":
            parts.append(float(np.mean(vec)))
        elif stat == "std":
            parts.append(float(np.std(vec)))
        elif stat == "min":
            parts.append(float(np.min(vec)))
        elif stat == "max":
            parts.append(float(np.max(vec)))
        elif stat == "median":
            parts.append(float(np.median(vec)))
        elif stat == "kurtosis":
            parts.append(float(_safe_kurtosis(vec)[0]))
        else:
            raise ValueError(f"Unsupported stat: {stat}")
    return np.asarray(parts, dtype=np.float64)


def _extract_features_for_path(audio_path: str) -> np.ndarray:
    expected_dim = 156
    try:
        y, sr = librosa.load(audio_path, sr=None, mono=True)
        y = np.asarray(y, dtype=np.float64)
        if y.size == 0:
            return np.zeros(expected_dim, dtype=np.float64)

        mfcc = librosa.feature.mfcc(y=y, sr=sr, n_mfcc=21)
        spectral_contrast = librosa.feature.spectral_contrast(y=y, sr=sr)
        spectral_bandwidth = librosa.feature.spectral_bandwidth(y=y, sr=sr)

        mfcc_feats = _aggregate_matrix_stats(
            mfcc,
            ("mean", "std", "min", "max", "median", "kurtosis"),
        )
        sc_feats = _aggregate_matrix_stats(
            spectral_contrast,
            ("mean", "std", "median", "min"),
        )
        bw_feats = _aggregate_vector_stats(
            spectral_bandwidth[0],
            ("mean", "std"),
        )

        feats = np.concatenate([mfcc_feats, sc_feats, bw_feats], axis=0)
        if feats.shape[0] != expected_dim:
            raise ValueError(f"Unexpected feature dimension: {feats.shape[0]}")
        return np.nan_to_num(feats, nan=0.0, posinf=0.0, neginf=0.0)
    except Exception:
        return np.zeros(expected_dim, dtype=np.float64)


def feature_fn(data_subset):
    features = [_extract_features_for_path(path) for path in data_subset]
    if len(features) == 0:
        return np.zeros((0, 156), dtype=np.float64)
    X_subset = np.vstack(features).astype(np.float64, copy=False)
    return np.nan_to_num(X_subset, nan=0.0, posinf=0.0, neginf=0.0)

import os
import numpy as np
import librosa


def _safe_stat_vector(values, stats):
    values = np.asarray(values, dtype=np.float64).ravel()
    values = values[np.isfinite(values)]
    if values.size == 0:
        values = np.zeros(1, dtype=np.float64)

    out = []
    for stat in stats:
        if stat == "mean":
            v = float(np.mean(values))
        elif stat == "std":
            v = float(np.std(values))
        elif stat == "min":
            v = float(np.min(values))
        elif stat == "max":
            v = float(np.max(values))
        elif stat == "median":
            v = float(np.median(values))
        elif stat == "kurtosis":
            centered = values - np.mean(values)
            var = float(np.mean(centered ** 2))
            if var <= 0.0:
                v = 0.0
            else:
                v = float(np.mean(centered ** 4) / (var ** 2) - 3.0)
        else:
            raise ValueError(f"Unsupported stat: {stat}")
        if not np.isfinite(v):
            v = 0.0
        out.append(v)
    return out


def _extract_features_from_path(audio_path):
    expected_dim = 157
    try:
        if not isinstance(audio_path, str) or not audio_path or not os.path.exists(audio_path):
            return np.zeros(expected_dim, dtype=np.float64)

        y, sr = librosa.load(audio_path, sr=None, mono=True)
        y = np.asarray(y, dtype=np.float64)
        if y.size == 0:
            return np.zeros(expected_dim, dtype=np.float64)

        n_fft = min(2048, y.size)
        if n_fft < 32:
            n_fft = y.size
        hop_length = max(1, n_fft // 4)

        mfcc = librosa.feature.mfcc(y=y, sr=sr, n_mfcc=21, n_fft=n_fft, hop_length=hop_length)
        spectral_contrast = librosa.feature.spectral_contrast(y=y, sr=sr, n_fft=n_fft, hop_length=hop_length)
        rms = librosa.feature.rms(y=y, frame_length=n_fft, hop_length=hop_length)[0]
        rms_diff = np.diff(rms) if rms.size > 1 else np.zeros(1, dtype=np.float64)

        features = []

        mfcc_stats = ("mean", "std", "min", "max", "median", "kurtosis")
        for i in range(mfcc.shape[0]):
            features.extend(_safe_stat_vector(mfcc[i], mfcc_stats))

        sc_stats = ("mean", "std", "median", "min")
        for i in range(spectral_contrast.shape[0]):
            features.extend(_safe_stat_vector(spectral_contrast[i], sc_stats))

        energy_stats = ("mean", "std", "kurtosis")
        features.extend(_safe_stat_vector(rms_diff, energy_stats))

        x = np.asarray(features, dtype=np.float64)
        if x.shape[0] != expected_dim:
            fixed = np.zeros(expected_dim, dtype=np.float64)
            fixed[: min(expected_dim, x.shape[0])] = x[:expected_dim]
            x = fixed
        x[~np.isfinite(x)] = 0.0
        return x
    except Exception:
        return np.zeros(expected_dim, dtype=np.float64)


def feature_fn(data_subset):
    rows = [_extract_features_from_path(audio_path) for audio_path in data_subset]
    if len(rows) == 0:
        return np.zeros((0, 157), dtype=np.float64)
    return np.vstack(rows).astype(np.float64, copy=False)

import numpy as np
import librosa
from scipy.stats import kurtosis


def _safe_kurtosis(x):
    x = np.asarray(x, dtype=np.float64)
    if x.size == 0:
        return 0.0
    if np.allclose(x, x[0]):
        return 0.0
    value = kurtosis(x, fisher=True, bias=False, nan_policy="omit")
    if not np.isfinite(value):
        return 0.0
    return float(value)


def _summary_stats_six(mat):
    mat = np.asarray(mat, dtype=np.float64)
    if mat.ndim != 2 or mat.shape[1] == 0:
        return np.zeros(mat.shape[0] * 6 if mat.ndim == 2 else 0, dtype=np.float64)
    mean = np.mean(mat, axis=1)
    std = np.std(mat, axis=1)
    minv = np.min(mat, axis=1)
    maxv = np.max(mat, axis=1)
    median = np.median(mat, axis=1)
    kurt = np.array([_safe_kurtosis(row) for row in mat], dtype=np.float64)
    return np.concatenate([mean, std, minv, maxv, median, kurt], axis=0)


def _summary_stats_four(mat):
    mat = np.asarray(mat, dtype=np.float64)
    if mat.ndim != 2 or mat.shape[1] == 0:
        return np.zeros(mat.shape[0] * 4 if mat.ndim == 2 else 0, dtype=np.float64)
    mean = np.mean(mat, axis=1)
    std = np.std(mat, axis=1)
    median = np.median(mat, axis=1)
    minv = np.min(mat, axis=1)
    return np.concatenate([mean, std, median, minv], axis=0)


def _extract_one(path):
    n_fft = 2048
    hop_length = 512
    split_hz = 2000.0
    eps = 1e-10
    expected_dim = 157

    try:
        y, sr = librosa.load(path, sr=None, mono=True)
        y = np.asarray(y, dtype=np.float64)
        if y.size == 0:
            return np.zeros(expected_dim, dtype=np.float64)

        mfcc = librosa.feature.mfcc(y=y, sr=sr, n_mfcc=21, n_fft=n_fft, hop_length=hop_length)
        mfcc_feats = _summary_stats_six(mfcc)

        spec_contrast = librosa.feature.spectral_contrast(y=y, sr=sr, n_fft=n_fft, hop_length=hop_length)
        sc_feats = _summary_stats_four(spec_contrast)

        stft_mag = np.abs(librosa.stft(y, n_fft=n_fft, hop_length=hop_length))
        power_spec = stft_mag ** 2
        freqs = librosa.fft_frequencies(sr=sr, n_fft=n_fft)
        low_mask = freqs < split_hz
        high_mask = freqs >= split_hz

        low_energy = power_spec[low_mask].sum(axis=0) if np.any(low_mask) else np.zeros(power_spec.shape[1], dtype=np.float64)
        high_energy = power_spec[high_mask].sum(axis=0) if np.any(high_mask) else np.zeros(power_spec.shape[1], dtype=np.float64)
        ratio = low_energy / (high_energy + eps)
        ratio_feats = np.array([
            float(np.mean(ratio)) if ratio.size else 0.0,
            float(np.std(ratio)) if ratio.size else 0.0,
            _safe_kurtosis(ratio),
        ], dtype=np.float64)

        feats = np.concatenate([mfcc_feats, sc_feats, ratio_feats], axis=0)
        if feats.shape[0] != expected_dim:
            fixed = np.zeros(expected_dim, dtype=np.float64)
            fixed[: min(expected_dim, feats.shape[0])] = feats[:expected_dim]
            feats = fixed
        feats = np.nan_to_num(feats, nan=0.0, posinf=0.0, neginf=0.0).astype(np.float64, copy=False)
        return feats
    except Exception:
        return np.zeros(expected_dim, dtype=np.float64)



def feature_fn(data_subset):
    features = [_extract_one(path) for path in data_subset]
    if len(features) == 0:
        return np.zeros((0, 157), dtype=np.float64)
    return np.vstack(features).astype(np.float64, copy=False)

