            ("mean", "std", "median", "min", "max", "kurtosis"),
        )

        spectral_contrast = librosa.feature.spectral_contrast(
            y=y,
            sr=sr,
            n_fft=2048,
            hop_length=512,
        )
        sc_feats = _aggregate_rows(
            spectral_contrast,
            ("mean", "std", "median", "min"),
        )

        rms = librosa.feature.rms(y=y, frame_length=2048, hop_length=512).reshape(-1)
        rms_derivative = np.diff(rms) if rms.size > 1 else np.array([], dtype=np.float64)
        rms_deriv_feats = _aggregate_vector(
            rms_derivative,
            ("mean", "std", "min", "max", "kurtosis"),
        )

        features = np.concatenate([mfcc_feats, sc_feats, rms_deriv_feats]).astype(np.float64, copy=False)
        if features.shape[0] != expected_dim:
            return np.zeros(expected_dim, dtype=np.float64)
        return np.nan_to_num(features, nan=0.0, posinf=0.0, neginf=0.0)
    except Exception:
        return np.zeros(expected_dim, dtype=np.float64)



