import numpy as np
import librosa


def _safe_kurtosis(x: np.ndarray) -> float:
    x = np.asarray(x, dtype=np.float64).ravel()
    if x.size == 0:
        return 0.0
    mean = float(np.mean(x))
    centered = x - mean
    var = float(np.mean(centered ** 2))
    if not np.isfinite(var) or var <= 0.0:
        return 0.0
    fourth = float(np.mean(centered ** 4))
    kurt = fourth / (var ** 2)
    if not np.isfinite(kurt):
        return 0.0
    return float(kurt)


def _aggregate_rows(mat: np.ndarray, stats: tuple[str, ...]) -> np.ndarray:
    mat = np.asarray(mat, dtype=np.float64)
    if mat.ndim != 2 or mat.shape[1] == 0:
        n_rows = mat.shape[0] if mat.ndim == 2 else 0
        return np.zeros(n_rows * len(stats), dtype=np.float64)

    parts = []
    for row in mat:
        row_parts = []
        for stat in stats:
            if stat == "mean":
                row_parts.append(float(np.mean(row)))
            elif stat == "std":
                row_parts.append(float(np.std(row)))
            elif stat == "median":
                row_parts.append(float(np.median(row)))
            elif stat == "min":
                row_parts.append(float(np.min(row)))
            elif stat == "max":
                row_parts.append(float(np.max(row)))
            elif stat == "kurtosis":
                row_parts.append(_safe_kurtosis(row))
            else:
                raise ValueError(f"Unsupported stat: {stat}")
        parts.extend(row_parts)
    return np.asarray(parts, dtype=np.float64)


def _extract_one(path: str) -> np.ndarray:
    expected_dim = 157
    try:
        y, sr = librosa.load(path, sr=None, mono=True)
        y = np.asarray(y, dtype=np.float64)
        if y.size == 0:
            return np.zeros(expected_dim, dtype=np.float64)

        mfcc = librosa.feature.mfcc(y=y, sr=sr, n_mfcc=21)
        mfcc_feat = _aggregate_rows(
            mfcc,
            ("mean", "std", "median", "min", "max", "kurtosis"),
        )

        sc = librosa.feature.spectral_contrast(y=y, sr=sr)
        sc_feat = _aggregate_rows(sc, ("mean", "std", "median", "min"))

        rms = librosa.feature.rms(y=y).ravel()
        if rms.size >= 3:
            rms_acc = np.diff(np.diff(rms))
            rms_feat = np.asarray(
                [
                    float(np.mean(rms_acc)),
                    float(np.std(rms_acc)),
                    _safe_kurtosis(rms_acc),
                ],
                dtype=np.float64,
            )
        else:
            rms_feat = np.zeros(3, dtype=np.float64)

        feat = np.concatenate([mfcc_feat, sc_feat, rms_feat]).astype(np.float64, copy=False)
        if feat.shape[0] != expected_dim:
            fixed = np.zeros(expected_dim, dtype=np.float64)
            fixed[: min(expected_dim, feat.shape[0])] = feat[:expected_dim]
            feat = fixed
        feat = np.nan_to_num(feat, nan=0.0, posinf=0.0, neginf=0.0)
        return feat
    except Exception:
        return np.zeros(expected_dim, dtype=np.float64)


def feature_fn(data_subset):
    features = [_extract_one(path) for path in data_subset]
    if len(features) == 0:
        return np.zeros((0, 157), dtype=np.float64)
    return np.vstack(features).astype(np.float64, copy=False)

import numpy as np
import librosa
from scipy.stats import kurtosis


def _safe_stat_summary(values, stats):
    values = np.asarray(values, dtype=np.float64)
    if values.size == 0:
        values = np.zeros(1, dtype=np.float64)
    values = np.nan_to_num(values, nan=0.0, posinf=0.0, neginf=0.0)

    out = []
    for stat in stats:
        if stat == "mean":
            out.append(float(np.mean(values)))
        elif stat == "std":
            out.append(float(np.std(values)))
        elif stat == "median":
            out.append(float(np.median(values)))
        elif stat == "min":
            out.append(float(np.min(values)))
        elif stat == "max":
            out.append(float(np.max(values)))
        elif stat == "kurtosis":
            if values.size < 4 or np.allclose(values, values[0]):
                out.append(0.0)
            else:
                k = float(kurtosis(values, fisher=True, bias=False, nan_policy="omit"))
                out.append(0.0 if not np.isfinite(k) else k)
        else:
            raise ValueError(f"Unsupported stat: {stat}")
    return out


def _frame_hnr(y, sr, frame_length, hop_length, fmin=75.0, fmax=500.0):
    if y.size == 0:
        return np.zeros(1, dtype=np.float64)

    frames = librosa.util.frame(y, frame_length=frame_length, hop_length=hop_length)
    if frames.size == 0:
        return np.zeros(1, dtype=np.float64)

    min_lag = max(1, int(sr / fmax))
    max_lag = min(frame_length - 1, int(sr / fmin))
    if min_lag >= max_lag:
        return np.zeros(frames.shape[1], dtype=np.float64)

    hnr_values = []
    for i in range(frames.shape[1]):
        frame = frames[:, i].astype(np.float64, copy=False)
        frame = frame - np.mean(frame)
        energy = float(np.dot(frame, frame))
        if energy <= 1e-12:
            hnr_values.append(0.0)
            continue

        ac = np.correlate(frame, frame, mode="full")[frame_length - 1:]
        r0 = float(ac[0])
        if r0 <= 1e-12:
            hnr_values.append(0.0)
            continue

        search = ac[min_lag:max_lag + 1]
        if search.size == 0:
            hnr_values.append(0.0)
            continue

        peak = float(np.max(search))
        ratio = peak / (r0 + 1e-12)
        if (not np.isfinite(ratio)) or ratio <= 0.0 or ratio >= 1.0:
            hnr_values.append(0.0)
            continue

        hnr = 10.0 * np.log10(ratio / (1.0 - ratio + 1e-12))
        hnr_values.append(0.0 if not np.isfinite(hnr) else hnr)

    hnr_values = np.asarray(hnr_values, dtype=np.float64)
    return np.nan_to_num(hnr_values, nan=0.0, posinf=0.0, neginf=0.0)


def _extract_one(path):
    target_dim = 159
    try:
        y, sr = librosa.load(path, sr=None, mono=True)
        y = np.asarray(y, dtype=np.float64)
        if y.size == 0:
            return np.zeros(target_dim, dtype=np.float64)

        n_fft = min(2048, max(256, int(2 ** np.ceil(np.log2(min(len(y), 2048))))))
        hop_length = max(128, n_fft // 4)
        frame_length = n_fft

        mfcc = librosa.feature.mfcc(y=y, sr=sr, n_mfcc=21, n_fft=n_fft, hop_length=hop_length)
        mfcc_stats = []
        for i in range(mfcc.shape[0]):
            mfcc_stats.extend(
                _safe_stat_summary(mfcc[i], ["mean", "std", "median", "min", "max", "kurtosis"])
            )

        contrast = librosa.feature.spectral_contrast(y=y, sr=sr, n_fft=n_fft, hop_length=hop_length)
        contrast_stats = []
        for i in range(contrast.shape[0]):
            contrast_stats.extend(
                _safe_stat_summary(contrast[i], ["mean", "std", "median", "min"])
            )

        rms = librosa.feature.rms(y=y, frame_length=frame_length, hop_length=hop_length)[0]
        rms_delta = np.diff(rms)
        rms_delta_stats = _safe_stat_summary(rms_delta, ["mean", "std", "kurtosis"])

        hnr_frames = _frame_hnr(y=y, sr=sr, frame_length=frame_length, hop_length=hop_length)
        hnr_stats = _safe_stat_summary(hnr_frames, ["mean", "std"])

        features = np.asarray(mfcc_stats + contrast_stats + rms_delta_stats + hnr_stats, dtype=np.float64)
        if features.size != target_dim:
            fixed = np.zeros(target_dim, dtype=np.float64)
            fixed[: min(target_dim, features.size)] = features[:target_dim]
            features = fixed
        return np.nan_to_num(features, nan=0.0, posinf=0.0, neginf=0.0)
    except Exception:
        return np.zeros(target_dim, dtype=np.float64)



def feature_fn(data_subset):
    features = [_extract_one(path) for path in data_subset]
    if len(features) == 0:
        return np.zeros((0, 159), dtype=np.float64)
    X_subset = np.vstack(features).astype(np.float64, copy=False)
    return np.nan_to_num(X_subset, nan=0.0, posinf=0.0, neginf=0.0)

import numpy as np
import librosa
from scipy.stats import kurtosis


def _safe_kurtosis(x):
    x = np.asarray(x, dtype=np.float64)
    if x.size == 0:
        return 0.0
    if np.allclose(x, x[0]):
        return 0.0
    value = kurtosis(x, fisher=True, bias=False)
    if not np.isfinite(value):
        return 0.0
    return float(value)


def _aggregate_rows(matrix, stats):
    matrix = np.asarray(matrix, dtype=np.float64)
    if matrix.ndim == 1:
        matrix = matrix[np.newaxis, :]
    features = []
    for row in matrix:
        for stat in stats:
            if stat == "mean":
                value = np.mean(row) if row.size else 0.0
            elif stat == "std":
                value = np.std(row) if row.size else 0.0
            elif stat == "median":
                value = np.median(row) if row.size else 0.0
            elif stat == "min":
                value = np.min(row) if row.size else 0.0
            elif stat == "max":
                value = np.max(row) if row.size else 0.0
            elif stat == "kurtosis":
                value = _safe_kurtosis(row)
            else:
                raise ValueError(f"Unsupported stat: {stat}")
            features.append(float(value) if np.isfinite(value) else 0.0)
    return np.asarray(features, dtype=np.float64)


def _extract_single(path):
    try:
        y, sr = librosa.load(path, sr=None, mono=True)
        y = np.asarray(y, dtype=np.float64)
        if y.size == 0:
            raise ValueError("empty audio")
    except Exception:
        return np.zeros(157, dtype=np.float64)

    mfcc = librosa.feature.mfcc(y=y, sr=sr, n_mfcc=21)
    mfcc_features = _aggregate_rows(
        mfcc,
        stats=("mean", "std", "median", "min", "max", "kurtosis"),
    )

    spectral_contrast = librosa.feature.spectral_contrast(y=y, sr=sr)
    contrast_features = _aggregate_rows(
        spectral_contrast,
        stats=("mean", "std", "median", "min"),
    )

    centroid = librosa.feature.spectral_centroid(y=y, sr=sr)[0]
    if centroid.size == 0:
        centroid_diff = np.zeros(1, dtype=np.float64)
    else:
        centroid_diff = np.diff(centroid, prepend=centroid[0])
    centroid_derivative_features = np.asarray(
        [
            float(np.mean(centroid_diff)) if centroid_diff.size else 0.0,
            float(np.std(centroid_diff)) if centroid_diff.size else 0.0,
            _safe_kurtosis(centroid_diff),
        ],
        dtype=np.float64,
    )

    features = np.concatenate(
        [mfcc_features, contrast_features, centroid_derivative_features],
        axis=0,
    )
    if features.shape[0] != 157:
        raise ValueError(f"Expected 157 features, got {features.shape[0]}")
    return np.nan_to_num(features, nan=0.0, posinf=0.0, neginf=0.0).astype(np.float64)


def feature_fn(data_subset):
    feature_list = [_extract_single(path) for path in data_subset]
    if len(feature_list) == 0:
        return np.zeros((0, 157), dtype=np.float64)
    X_subset = np.vstack(feature_list).astype(np.float64)
    return np.nan_to_num(X_subset, nan=0.0, posinf=0.0, neginf=0.0)

import numpy as np
import librosa


def _safe_load_audio(path):
    y, sr = librosa.load(path, sr=None, mono=True)
    if y.size == 0:
        return np.zeros(1, dtype=np.float32), 22050
    y = np.asarray(y, dtype=np.float32)
    if not np.all(np.isfinite(y)):
        y = np.nan_to_num(y, nan=0.0, posinf=0.0, neginf=0.0)
    return y, sr


def _aggregate_stats_6(matrix):
    mean = np.mean(matrix, axis=1)
    std = np.std(matrix, axis=1)
    median = np.median(matrix, axis=1)
    minv = np.min(matrix, axis=1)
    maxv = np.max(matrix, axis=1)
    rangev = maxv - minv
    return np.concatenate([mean, std, median, minv, maxv, rangev], axis=0)


def _aggregate_stats_4(matrix):
    mean = np.mean(matrix, axis=1)
    std = np.std(matrix, axis=1)
    median = np.median(matrix, axis=1)
    minv = np.min(matrix, axis=1)
    return np.concatenate([mean, std, median, minv], axis=0)


def _derivative_stats_2(sequence):
    sequence = np.asarray(sequence, dtype=np.float64).reshape(-1)
    if sequence.size < 2:
        return np.zeros(2, dtype=np.float64)
    delta = np.diff(sequence)
    return np.array([np.mean(delta), np.std(delta)], dtype=np.float64)


def _extract_one(path):
    expected_dim = 158
    try:
        y, sr = _safe_load_audio(path)
        n_fft = min(2048, max(256, int(2 ** np.floor(np.log2(max(256, min(len(y), 2048)))))))
        hop_length = max(1, n_fft // 4)

        mfcc = librosa.feature.mfcc(y=y, sr=sr, n_mfcc=21, n_fft=n_fft, hop_length=hop_length)
        sc = librosa.feature.spectral_contrast(y=y, sr=sr, n_fft=n_fft, hop_length=hop_length)
        rms = librosa.feature.rms(y=y, frame_length=n_fft, hop_length=hop_length)[0]
        centroid = librosa.feature.spectral_centroid(y=y, sr=sr, n_fft=n_fft, hop_length=hop_length)[0]

        mfcc_stats = _aggregate_stats_6(mfcc)
        sc_stats = _aggregate_stats_4(sc)
        rms_delta_stats = _derivative_stats_2(rms)
        centroid_delta_stats = _derivative_stats_2(centroid)

        features = np.concatenate(
            [mfcc_stats, sc_stats, rms_delta_stats, centroid_delta_stats],
            axis=0,
        ).astype(np.float64, copy=False)

        if features.shape[0] != expected_dim:
            fixed = np.zeros(expected_dim, dtype=np.float64)
            fixed[: min(expected_dim, features.shape[0])] = features[:expected_dim]
            features = fixed

        features = np.nan_to_num(features, nan=0.0, posinf=0.0, neginf=0.0)
        return features
    except Exception:
        return np.zeros(expected_dim, dtype=np.float64)



def feature_fn(data_subset):
    features = [_extract_one(path) for path in data_subset]
    if len(features) == 0:
        return np.zeros((0, 158), dtype=np.float64)
    X_subset = np.vstack(features).astype(np.float64, copy=False)
    X_subset = np.nan_to_num(X_subset, nan=0.0, posinf=0.0, neginf=0.0)
    return X_subset

import numpy as np
import librosa
from scipy.stats import kurtosis


def _sanitize_vector(vec, expected_dim):
    vec = np.asarray(vec, dtype=np.float64).reshape(-1)
    if vec.size != expected_dim:
        if vec.size < expected_dim:
            vec = np.pad(vec, (0, expected_dim - vec.size), mode="constant")
        else:
            vec = vec[:expected_dim]
    return np.nan_to_num(vec, nan=0.0, posinf=0.0, neginf=0.0)


def _framewise_stats(matrix):
    matrix = np.asarray(matrix, dtype=np.float64)
    if matrix.ndim != 2 or matrix.shape[1] == 0:
        return np.zeros(matrix.shape[0] * 6 if matrix.ndim == 2 else 0, dtype=np.float64)

    mean = np.mean(matrix, axis=1)
    std = np.std(matrix, axis=1)
    median = np.median(matrix, axis=1)
    min_ = np.min(matrix, axis=1)
    max_ = np.max(matrix, axis=1)
    kurt = kurtosis(matrix, axis=1, fisher=True, bias=False, nan_policy="omit")
    kurt = np.nan_to_num(kurt, nan=0.0, posinf=0.0, neginf=0.0)

    parts = []
    for i in range(matrix.shape[0]):
        parts.extend([mean[i], std[i], median[i], min_[i], max_[i], kurt[i]])
    return np.asarray(parts, dtype=np.float64)


def _vector_stats(values):
    values = np.asarray(values, dtype=np.float64).reshape(-1)
    if values.size == 0:
        return np.zeros(3, dtype=np.float64)
    mean = float(np.mean(values))
    std = float(np.std(values))
    kurt = float(kurtosis(values, fisher=True, bias=False, nan_policy="omit"))
    if not np.isfinite(kurt):
        kurt = 0.0
    return np.asarray([mean, std, kurt], dtype=np.float64)


def _extract_one(path):
    expected_dim = 157
    try:
        y, sr = librosa.load(path, sr=None, mono=True)
        y = np.asarray(y, dtype=np.float64)
        if y.size == 0:
            return np.zeros(expected_dim, dtype=np.float64)

        mfcc = librosa.feature.mfcc(y=y, sr=sr, n_mfcc=21)
        mfcc_stats = _framewise_stats(mfcc)

        spectral_contrast = librosa.feature.spectral_contrast(y=y, sr=sr, n_fft=2048, hop_length=512)
        sc_matrix = spectral_contrast[:7] if spectral_contrast.shape[0] >= 7 else spectral_contrast
        sc_mean = np.mean(sc_matrix, axis=1)
        sc_std = np.std(sc_matrix, axis=1)
        sc_median = np.median(sc_matrix, axis=1)
        sc_min = np.min(sc_matrix, axis=1)
        sc_stats = np.concatenate([sc_mean, sc_std, sc_median, sc_min]).astype(np.float64, copy=False)

        magnitude = np.abs(librosa.stft(y=y, n_fft=2048, hop_length=512))
        if magnitude.shape[1] >= 2:
            diffs = np.diff(magnitude, axis=1)
            flux = np.linalg.norm(diffs, axis=0)
        else:
            flux = np.zeros(1, dtype=np.float64)
        flux_stats = _vector_stats(flux)

        features = np.concatenate([mfcc_stats, sc_stats, flux_stats])
        return _sanitize_vector(features, expected_dim)
    except Exception:
        return np.zeros(expected_dim, dtype=np.float64)



def feature_fn(data_subset):
    features = [_extract_one(path) for path in data_subset]
    if len(features) == 0:
        return np.zeros((0, 157), dtype=np.float64)
    return np.vstack(features).astype(np.float64, copy=False)
